// Cobra Code — Python de verdade (Pyodide) rodando num Web Worker.
import { loadPyodide } from "./py/pyodide.mjs";

const HARNESS = "\"\"\"Cobra Code \u2014 motor de execu\u00e7\u00e3o e corre\u00e7\u00e3o.\n\nRoda dentro do navegador (Pyodide, num Web Worker) e tamb\u00e9m localmente\n(para verificar as aulas). Nada aqui depende do navegador.\n\"\"\"\nimport ast\nimport builtins\nimport io\nimport json\nimport linecache\nimport math\nimport os\nimport random\nimport re\nimport sys\nimport textwrap\nimport time\nimport traceback\nimport types\nimport unicodedata\n\nimport hashlib as _hashlib  # noqa: E402\n\nif not hasattr(_hashlib, \"pbkdf2_hmac\"):\n    _TRANS_5C = bytes((x ^ 0x5C) for x in range(256))\n    _TRANS_36 = bytes((x ^ 0x36) for x in range(256))\n\n    def _pbkdf2_hmac(hash_name, password, salt, iterations, dklen=None):\n        \"\"\"Password based key derivation function 2 (PKCS #5 v2.0) with HMAC as pseudorandom function.\"\"\"\n        if not isinstance(hash_name, str):\n            raise TypeError(hash_name)\n        if not isinstance(password, (bytes, bytearray)):\n            password = bytes(memoryview(password))\n        if not isinstance(salt, (bytes, bytearray)):\n            salt = bytes(memoryview(salt))\n        inner = _hashlib.new(hash_name)\n        outer = _hashlib.new(hash_name)\n        blocksize = getattr(inner, \"block_size\", 64)\n        if len(password) > blocksize:\n            password = _hashlib.new(hash_name, password).digest()\n        password = password + b\"\\x00\" * (blocksize - len(password))\n        inner.update(password.translate(_TRANS_36))\n        outer.update(password.translate(_TRANS_5C))\n\n        def prf(msg, inner=inner, outer=outer):\n            icpy = inner.copy()\n            ocpy = outer.copy()\n            icpy.update(msg)\n            ocpy.update(icpy.digest())\n            return ocpy.digest()\n\n        if iterations < 1:\n            raise ValueError(iterations)\n        if dklen is None:\n            dklen = outer.digest_size\n        if dklen < 1:\n            raise ValueError(dklen)\n        dkey = b\"\"\n        loop = 1\n        while len(dkey) < dklen:\n            prev = prf(salt + loop.to_bytes(4, \"big\"))\n            rkey = int.from_bytes(prev, \"big\")\n            for _ in range(iterations - 1):\n                prev = prf(prev)\n                rkey ^= int.from_bytes(prev, \"big\")\n            loop += 1\n            dkey += rkey.to_bytes(inner.digest_size, \"big\")\n        return dkey[:dklen]\n\n    _hashlib.pbkdf2_hmac = _pbkdf2_hmac\n\nARQUIVO = \"main.py\"\nLIMITE_SAIDA = 60_000\nTEMPO_EXECUTAR = 5.0   # segundos para o bot\u00e3o Executar\nTEMPO_TESTES = 8.0     # segundos para a bateria de testes inteira\n\n\n# ----------------------------------------------------------------------------\n# Sinais internos (BaseException: o \"except Exception\" do aluno n\u00e3o os captura)\n# ----------------------------------------------------------------------------\nclass _SinalEntrada(BaseException):\n    def __init__(self, prompt):\n        super().__init__(prompt)\n        self.prompt = prompt\n\n\nclass _SinalSaidaDemais(BaseException):\n    pass\n\n\nclass _SinalTempo(BaseException):\n    def __init__(self, linha):\n        super().__init__(linha)\n        self.linha = linha\n\n\nclass _SinalInputProibido(BaseException):\n    pass\n\n\n_IDENT = re.compile(r\"[A-Za-z_\u00c0-\u00ff][\\w]*\")\n\n\ndef _maiuscula(msg):\n    \"\"\"Primeira letra mai\u00fascula \u2014 exceto quando a frase come\u00e7a com um nome de c\u00f3digo (area(3), p.vida, x_y).\"\"\"\n    m = _IDENT.match(msg)\n    if not m or not msg[:1].islower():\n        return msg\n    palavra = m.group(0)\n    seguinte = msg[m.end():m.end() + 1]\n    if \"_\" in palavra or seguinte in (\"(\", \".\", \"[\", \"_\"):\n        return msg\n    return msg[:1].upper() + msg[1:]\n\n\nclass FalhaTeste(Exception):\n    def __init__(self, msg, esperado=None, recebido=None):\n        msg = _maiuscula(str(msg))\n        super().__init__(msg)\n        self.msg = msg\n        self.esperado = esperado\n        self.recebido = recebido\n\n\n# ----------------------------------------------------------------------------\n# Rel\u00f3gio: interrompe loops infinitos silenciosos (checa o tempo a cada 1024 linhas)\n# ----------------------------------------------------------------------------\nclass _Relogio:\n    limite = None\n    passos = 0\n\n\ndef _rastro_local(frame, evento, arg):\n    if evento == \"line\":\n        _Relogio.passos += 1\n        if not (_Relogio.passos & 1023) and _Relogio.limite is not None and time.perf_counter() > _Relogio.limite:\n            raise _SinalTempo(frame.f_lineno)\n    return _rastro_local\n\n\ndef _rastro_global(frame, evento, arg):\n    if frame.f_code.co_filename == ARQUIVO:\n        return _rastro_local\n    return None\n\n\ndef _armar_relogio(segundos):\n    _Relogio.limite = time.perf_counter() + segundos\n    sys.settrace(_rastro_global)\n\n\ndef _desarmar_relogio():\n    sys.settrace(None)\n    _Relogio.limite = None\n\n\nclass _Saida(io.TextIOBase):\n    def __init__(self, limite=LIMITE_SAIDA):\n        self._partes = []\n        self._n = 0\n        self._limite = limite\n\n    def writable(self):\n        return True\n\n    def write(self, s):\n        if not isinstance(s, str):\n            raise TypeError(f\"write() argument must be str, not {type(s).__name__}\")\n        self._n += len(s)\n        if self._n > self._limite:\n            raise _SinalSaidaDemais()\n        self._partes.append(s)\n        return len(s)\n\n    def flush(self):\n        pass\n\n    def getvalue(self):\n        return \"\".join(self._partes)\n\n\n# ----------------------------------------------------------------------------\n# Execu\u00e7\u00e3o do c\u00f3digo do aluno\n# ----------------------------------------------------------------------------\nclass Resultado:\n    def __init__(self):\n        self.saida = \"\"\n        self.ns = {}\n        self.erro = None\n        self.prompts = []\n        self.entradas = []\n        self.entradas_usadas = 0\n        self.prompt_pendente = None\n        self.fim = \"ok\"  # ok | erro | entrada | limite | exit\n        self.contexto = \"\"\n\n    @property\n    def linhas(self):\n        return _linhas(self.saida)\n\n    def __repr__(self):\n        return f\"<Resultado fim={self.fim} saida={self.saida[:60]!r}>\"\n\n\ndef _registrar_fonte(codigo):\n    linhas = codigo.splitlines(True)\n    if linhas and not linhas[-1].endswith(\"\\n\"):\n        linhas[-1] += \"\\n\"\n    linecache.cache[ARQUIVO] = (len(codigo), None, linhas, ARQUIVO)\n\n\ndef _preparar_arquivos(arquivos):\n    for nome, conteudo in (arquivos or {}).items():\n        with open(nome, \"w\", encoding=\"utf-8\") as f:\n            f.write(conteudo)\n\n\ndef _executar(codigo, entradas=None, semente=None, eco=False, nome_modulo=\"__main__\"):\n    r = Resultado()\n    r.entradas = [str(x) for x in (entradas or [])]\n    out = _Saida()\n\n    def _input(prompt=\"\"):\n        prompt = str(prompt)\n        r.prompts.append(prompt)\n        if eco and prompt:\n            out.write(prompt)\n        if r.entradas_usadas >= len(r.entradas):\n            raise _SinalEntrada(prompt)\n        valor = r.entradas[r.entradas_usadas]\n        r.entradas_usadas += 1\n        if eco:\n            out.write(\"\\x01\" + valor + \"\\x02\\n\")  # marcadores: o console pinta o que foi digitado\n        return valor\n\n    modulo = types.ModuleType(nome_modulo)\n    modulo.__file__ = ARQUIVO\n    modulo.__builtins__ = builtins\n    ns = modulo.__dict__\n    # registra o m\u00f3dulo enquanto o c\u00f3digo roda: unittest.main() e doctest procuram o __main__ em sys.modules\n    registrar = nome_modulo == \"__main__\" or nome_modulo not in sys.modules\n    modulo_antigo = sys.modules.get(nome_modulo)\n    _registrar_fonte(codigo)\n    try:\n        _reiniciar_logging()\n    except NameError:\n        pass\n    velhos = (sys.stdout, sys.stderr, builtins.input)\n    sys.stdout = out\n    sys.stderr = out\n    builtins.input = _input\n    random.seed(semente if semente is not None else random.randrange(1 << 30))\n    limite_rec = sys.getrecursionlimit()\n    if registrar:\n        sys.modules[nome_modulo] = modulo\n    try:\n        obj = compile(codigo, ARQUIVO, \"exec\")\n        exec(obj, ns)\n    except _SinalEntrada as s:\n        r.fim = \"entrada\"\n        r.prompt_pendente = s.prompt\n    except _SinalSaidaDemais:\n        r.fim = \"limite\"\n    except _SinalTempo as t:\n        r.fim = \"tempo\"\n        r.linha_tempo = t.linha\n    except SystemExit:\n        r.fim = \"exit\"\n    except BaseException as e:  # noqa: BLE001 - queremos tudo\n        r.fim = \"erro\"\n        r.erro = e\n    finally:\n        sys.stdout, sys.stderr, builtins.input = velhos\n        sys.setrecursionlimit(limite_rec)\n        if registrar:\n            if modulo_antigo is None:\n                sys.modules.pop(nome_modulo, None)\n            else:\n                sys.modules[nome_modulo] = modulo_antigo\n    r.saida = out.getvalue()\n    r.ns = ns\n    return r\n\n\n# ----------------------------------------------------------------------------\n# Mensagens de erro amig\u00e1veis\n# ----------------------------------------------------------------------------\ndef _filtrar_te(te):\n    vistos = set()\n    atual = te\n    while atual is not None and id(atual) not in vistos:\n        vistos.add(id(atual))\n        if atual.stack is not None:\n            quadros = [f for f in atual.stack if f.filename == ARQUIVO]\n            atual.stack = traceback.StackSummary.from_list(quadros)\n        atual = atual.__cause__ or atual.__context__\n\n\ndef _texto_erro(e):\n    try:\n        te = traceback.TracebackException(type(e), e, e.__traceback__, compact=True)\n        _filtrar_te(te)\n        return \"\".join(te.format()).rstrip(\"\\n\")\n    except Exception:  # noqa: BLE001\n        return f\"{type(e).__name__}: {e}\"\n\n\ndef _linha_erro(e):\n    if isinstance(e, SyntaxError):\n        return e.lineno\n    tb = e.__traceback__\n    linha = None\n    while tb is not None:\n        if tb.tb_frame.f_code.co_filename == ARQUIVO:\n            linha = tb.tb_lineno\n        tb = tb.tb_next\n    return linha\n\n\ndef _explicar(e):\n    \"\"\"Explica\u00e7\u00e3o curta, em portugu\u00eas, para os erros mais comuns.\"\"\"\n    _sq = sys.modules.get(\"sqlite3\")\n    if _sq is not None and isinstance(e, _sq.Error):\n        return _explicar_sql(e)\n    nome = type(e).__name__\n    msg = str(e)\n    if isinstance(e, SyntaxError):\n        m = (e.msg or \"\").lower()\n        if isinstance(e, TabError):\n            return \"Voc\u00ea misturou Tab e espa\u00e7os na indenta\u00e7\u00e3o. Use s\u00f3 espa\u00e7os (4 por n\u00edvel).\"\n        if isinstance(e, IndentationError):\n            if \"expected an indented block\" in m:\n                return (\"Depois de uma linha que termina com dois-pontos (:), as linhas do bloco \"\n                        \"precisam come\u00e7ar com espa\u00e7os (4 \u00e9 o padr\u00e3o).\")\n            if \"unexpected indent\" in m:\n                return \"Esta linha come\u00e7a com espa\u00e7os sem motivo. Tire a indenta\u00e7\u00e3o ou confira o bloco de cima.\"\n            if \"unindent\" in m:\n                return \"A indenta\u00e7\u00e3o ficou desalinhada: as linhas de um mesmo bloco precisam come\u00e7ar na mesma coluna.\"\n            return \"Problema de indenta\u00e7\u00e3o (os espa\u00e7os no come\u00e7o das linhas).\"\n        if \"never closed\" in m:\n            return \"Voc\u00ea abriu um par\u00eantese, colchete ou chave e n\u00e3o fechou. Confira se cada ( tem seu ).\"\n        if \"unterminated string\" in m or \"unterminated triple-quoted\" in m or \"eol while scanning\" in m:\n            return \"Um texto (string) come\u00e7ou com aspas e n\u00e3o terminou. Feche as aspas na mesma linha.\"\n        if \"unmatched\" in m or \"does not match opening\" in m:\n            return \"Tem um par\u00eantese/colchete/chave fechando sem ter sido aberto (ou fechando o tipo errado).\"\n        if \"expected ':'\" in m:\n            return \"Faltaram os dois-pontos (:) no fim da linha \u2014 if, elif, else, for, while, def e class terminam com :\"\n        if \"missing parentheses in call to 'print'\" in m:\n            return \"No Python 3, print precisa de par\u00eanteses: print(\\\"texto\\\").\"\n        if \"'=='\" in m or '\"==\"' in m or \"cannot assign to comparison\" in m:\n            return \"Para comparar, use == (dois sinais). Um = sozinho serve para guardar um valor numa vari\u00e1vel.\"\n        if \"cannot assign to\" in m:\n            return \"Do lado esquerdo do = precisa ficar o nome de uma vari\u00e1vel (ex.: idade = 15).\"\n        if \"invalid character\" in m:\n            return (\"Tem um caractere que o Python n\u00e3o entende. Cuidado com aspas curvas (\u201c \u201d \u2018 \u2019) \"\n                    \"copiadas de outros lugares: use aspas retas \\\" ou '.\")\n        if \"invalid decimal literal\" in m or \"invalid digit\" in m:\n            return \"Um nome n\u00e3o pode come\u00e7ar com n\u00famero, e n\u00fameros n\u00e3o podem ter letras grudadas (ex.: 2x).\"\n        if \"leading zeros\" in m:\n            return \"N\u00fameros inteiros n\u00e3o podem come\u00e7ar com zero (escreva 7 em vez de 07).\"\n        if \"perhaps you forgot a comma\" in m:\n            return \"Parece que faltou uma v\u00edrgula entre dois valores.\"\n        if \"'return' outside function\" in m:\n            return \"return s\u00f3 pode ser usado dentro de uma fun\u00e7\u00e3o (def).\"\n        if \"'break' outside loop\" in m or \"'continue'\" in m and \"loop\" in m:\n            return \"break e continue s\u00f3 funcionam dentro de um la\u00e7o (for ou while).\"\n        if \"expected 'except' or 'finally'\" in m:\n            return \"Todo try precisa de pelo menos um except (ou finally) logo depois do bloco.\"\n        if \"invalid syntax\" in m:\n            return (\"O Python n\u00e3o entendeu esta linha. Confira aspas, par\u00eanteses, dois-pontos e se n\u00e3o \"\n                    \"faltou um operador (+, -, *, ...). \u00c0s vezes o erro de verdade est\u00e1 na linha de cima.\")\n        return \"Erro de sintaxe: o c\u00f3digo n\u00e3o segue as regras de escrita do Python. Confira a linha indicada.\"\n    if isinstance(e, UnboundLocalError):\n        return (\"Dentro da fun\u00e7\u00e3o voc\u00ea usou uma vari\u00e1vel antes de dar um valor a ela. Se a ideia era mexer \"\n                \"na vari\u00e1vel de fora, passe-a como par\u00e2metro (ou, em \u00faltimo caso, use global).\")\n    if isinstance(e, NameError):\n        nome_var = getattr(e, \"name\", None) or (msg.split(\"'\")[1] if \"'\" in msg else \"?\")\n        dica = f\"O Python n\u00e3o conhece o nome '{nome_var}'. \"\n        sugestao = \"\"\n        if \"did you mean\" in msg.lower():\n            sugestao = msg[msg.lower().index(\"did you mean\"):].split(\":\", 1)[-1].strip().rstrip(\"?\")\n        if sugestao:\n            dica += f\"Talvez voc\u00ea quis escrever {sugestao}. \"\n        else:\n            dica += (\"Voc\u00ea criou essa vari\u00e1vel/fun\u00e7\u00e3o antes de usar? Mai\u00fasculas e min\u00fasculas contam. \"\n                     \"Se era um texto, faltaram as aspas.\")\n        return dica\n    if isinstance(e, TypeError):\n        ml = msg.lower()\n        if \"can only concatenate str\" in ml or (\"unsupported operand\" in ml and \"str\" in ml):\n            return (\"Voc\u00ea misturou texto (str) com n\u00famero numa conta ou com +. Converta: str(numero) para juntar \"\n                    \"com texto, ou int(texto)/float(texto) para fazer contas. Dica: input() sempre devolve texto.\")\n        if \"not supported between instances of\" in ml:\n            return (\"Voc\u00ea comparou valores de tipos diferentes (por exemplo texto com n\u00famero). \"\n                    \"Lembre: input() devolve texto \u2014 use int(input()) para ler n\u00fameros.\")\n        if \"not all arguments converted during string formatting\" in ml:\n            return (\"Voc\u00ea usou % com um texto (str). Se a ideia era calcular o resto da divis\u00e3o, converta \"\n                    \"o texto em n\u00famero antes com int(...) \u2014 lembre que input() devolve texto.\")\n        if \"returned non-string\" in ml:\n            return (\"O m\u00e9todo __str__ (ou __repr__) precisa DEVOLVER um texto com return, \"\n                    \"n\u00e3o mostrar com print.\")\n        if \"missing\" in ml and \"required positional argument\" in ml:\n            return \"A fun\u00e7\u00e3o foi chamada com argumentos a menos do que os par\u00e2metros que ela pede.\"\n        if \"positional argument\" in ml and \"were given\" in ml:\n            return (\"A fun\u00e7\u00e3o/m\u00e9todo recebeu mais argumentos do que os par\u00e2metros que tem. Em classes, confira \"\n                    \"se o m\u00e9todo tem self como primeiro par\u00e2metro e se o __init__ recebe todos os valores passados.\")\n        if \"unexpected keyword argument\" in ml:\n            return \"A fun\u00e7\u00e3o foi chamada com um nome de par\u00e2metro que ela n\u00e3o tem.\"\n        if \"object is not callable\" in ml:\n            return (\"Voc\u00ea usou par\u00eanteses () em algo que n\u00e3o \u00e9 fun\u00e7\u00e3o. \u00c0s vezes \u00e9 uma vari\u00e1vel com o mesmo \"\n                    \"nome de uma fun\u00e7\u00e3o (ex.: sum = 10 e depois sum(lista)).\")\n        if \"not subscriptable\" in ml:\n            return \"Voc\u00ea usou colchetes [ ] em um valor que n\u00e3o \u00e9 lista, texto, tupla nem dicion\u00e1rio.\"\n        if \"not iterable\" in ml:\n            return (\"Voc\u00ea tentou percorrer (for) algo que n\u00e3o \u00e9 uma sequ\u00eancia. Para repetir n vezes, \"\n                    \"use range(n).\")\n        if \"object does not support item assignment\" in ml:\n            return \"Esse tipo n\u00e3o pode ser alterado por \u00edndice (textos e tuplas s\u00e3o imut\u00e1veis).\"\n        if \"unhashable type\" in ml:\n            return \"Listas e dicion\u00e1rios n\u00e3o podem ser chaves de dicion\u00e1rio nem itens de conjunto. Use uma tupla.\"\n        if \"object cannot be interpreted as an integer\" in ml:\n            return \"Era preciso um n\u00famero inteiro aqui (por exemplo em range()). Converta com int().\"\n        if \"argument must be\" in ml or \"must be str\" in ml or \"must be real number\" in ml:\n            return \"Um valor de tipo errado foi passado para uma fun\u00e7\u00e3o. Confira se \u00e9 texto ou n\u00famero.\"\n        return \"Erro de tipo: uma opera\u00e7\u00e3o recebeu um valor de tipo inesperado.\"\n    if isinstance(e, ValueError):\n        ml = msg.lower()\n        if \"invalid literal for int()\" in ml:\n            return \"int() recebeu um texto que n\u00e3o \u00e9 um n\u00famero inteiro (ex.: letras, espa\u00e7o ou v\u00edrgula).\"\n        if \"could not convert string to float\" in ml:\n            return \"float() recebeu um texto que n\u00e3o \u00e9 um n\u00famero. Use ponto para decimais: 3.5, n\u00e3o 3,5.\"\n        if \"not enough values to unpack\" in ml or \"too many values to unpack\" in ml:\n            return \"A quantidade de vari\u00e1veis \u00e0 esquerda do = n\u00e3o bate com a quantidade de valores \u00e0 direita.\"\n        if \"not in list\" in ml:\n            return \"Voc\u00ea procurou/removeu um item que n\u00e3o est\u00e1 na lista. Confira com 'in' antes.\"\n        return \"Valor inv\u00e1lido para essa opera\u00e7\u00e3o.\"\n    if isinstance(e, ZeroDivisionError):\n        return \"Divis\u00e3o por zero n\u00e3o existe. Confira se o divisor pode ser 0 antes de dividir.\"\n    if isinstance(e, IndexError):\n        return (\"\u00cdndice fora do limite. Lembre que o primeiro \u00edndice \u00e9 0 e o \u00faltimo \u00e9 len(...) - 1. \"\n                \"Em uma lista vazia, nenhum \u00edndice existe.\")\n    if isinstance(e, KeyError):\n        return (\"Essa chave n\u00e3o existe no dicion\u00e1rio. Confira a grafia, verifique antes com 'in' \"\n                \"ou use .get(chave, padrao).\")\n    if isinstance(e, AttributeError):\n        if \"nonetype\" in msg.lower():\n            return (\"Voc\u00ea usou um m\u00e9todo em None. Algum m\u00e9todo/fun\u00e7\u00e3o devolveu None (por exemplo, \"\n                    \"lista.sort() e lista.append() n\u00e3o devolvem nada).\")\n        return \"Esse valor n\u00e3o tem esse atributo/m\u00e9todo. Confira o nome e o tipo do valor.\"\n    if isinstance(e, RecursionError):\n        return \"A fun\u00e7\u00e3o chamou a si mesma sem parar (recurs\u00e3o infinita). Falta um caso base que pare as chamadas?\"\n    if isinstance(e, ModuleNotFoundError):\n        return \"Esse m\u00f3dulo n\u00e3o existe aqui. Confira o nome (aqui temos a biblioteca padr\u00e3o do Python).\"\n    if isinstance(e, ImportError):\n        return \"N\u00e3o foi poss\u00edvel importar esse nome do m\u00f3dulo. Confira a grafia.\"\n    if isinstance(e, FileNotFoundError):\n        return \"O arquivo n\u00e3o foi encontrado. Confira o nome \u2014 ou crie-o antes de ler.\"\n    if isinstance(e, AssertionError):\n        return \"Um assert falhou: a condi\u00e7\u00e3o que voc\u00ea afirmou era falsa.\"\n    if isinstance(e, StopIteration):\n        return \"O iterador acabou: next() foi chamado depois do \u00faltimo item.\"\n    if isinstance(e, OverflowError):\n        return \"O n\u00famero ficou grande demais para essa opera\u00e7\u00e3o.\"\n    if isinstance(e, MemoryError):\n        return \"Acabou a mem\u00f3ria \u2014 provavelmente uma lista crescendo sem parar.\"\n    return f\"Aconteceu um {nome}.\"\n\n\ndef _info_erro(e):\n    return {\n        \"tipo\": type(e).__name__,\n        \"texto\": _texto_erro(e),\n        \"linha\": _linha_erro(e),\n        \"dica\": _explicar(e),\n    }\n\n\ndef _resumo_erro(e):\n    info = _info_erro(e)\n    return f\"{info['texto']}\\n\u2192 {info['dica']}\"\n\n\n# ----------------------------------------------------------------------------\n# Ajudantes para os testes das aulas\n# ----------------------------------------------------------------------------\ndef _linhas(texto):\n    ls = [l.rstrip() for l in str(texto).replace(\"\\r\\n\", \"\\n\").split(\"\\n\")]\n    while ls and ls[-1] == \"\":\n        ls.pop()\n    return ls\n\n\ndef _sem_acentos(s):\n    return \"\".join(c for c in unicodedata.normalize(\"NFD\", s) if unicodedata.category(c) != \"Mn\")\n\n\ndef _so_alfanum(s):\n    return \"\".join(c for c in s if c.isalnum())\n\n\ndef _pista(esp, rec):\n    if esp.lower() == rec.lower():\n        return \"A diferen\u00e7a est\u00e1 nas letras mai\u00fasculas/min\u00fasculas.\"\n    if esp.replace(\" \", \"\") == rec.replace(\" \", \"\"):\n        return \"A diferen\u00e7a est\u00e1 nos espa\u00e7os.\"\n    if _sem_acentos(esp) == _sem_acentos(rec):\n        return \"A diferen\u00e7a est\u00e1 nos acentos.\"\n    if esp.replace(\"-\", \"\") == rec.replace(\"-\", \"\") and _so_alfanum(esp):\n        return \"A diferen\u00e7a est\u00e1 no sinal de menos (-).\"\n    if _so_alfanum(esp) and _so_alfanum(esp) == _so_alfanum(rec):\n        return \"A diferen\u00e7a est\u00e1 na pontua\u00e7\u00e3o ou nos s\u00edmbolos (v\u00edrgulas, pontos, dois-pontos, exclama\u00e7\u00e3o...).\"\n    a, b = _so_alfanum(_sem_acentos(esp)).lower(), _so_alfanum(_sem_acentos(rec)).lower()\n    if a and a == b:\n        return \"Est\u00e1 quase: confira mai\u00fasculas, acentos e pontua\u00e7\u00e3o.\"\n    return None\n\n\n# ----------------------------------------------------------------------------\n# Corre\u00e7\u00e3o tranquila: sa\u00edda parecida passa (com uma dica) e o \"jeito de resolver\" vira sugest\u00e3o\n# ----------------------------------------------------------------------------\n# Os n\u00fameros precisam ser exatamente os mesmos (na mesma ordem); o texto pode diferir em espa\u00e7os, pontua\u00e7\u00e3o,\n# acentos, mai\u00fasculas (a n\u00e3o ser que a aula mexa com mai\u00fasculas: caixa) e em um ou outro erro de digita\u00e7\u00e3o.\n# Linhas em branco n\u00e3o contam. Se a aula alinha texto com espa\u00e7os (espacos), s\u00f3 mai\u00fasculas e acentos s\u00e3o\n# perdoados. Mesma l\u00f3gica de web/cpp/correcao.js e dos ajudantes de JavaScript.\nclass _Leniencia:\n    ativa = False\n    caixa = False\n    espacos = False\n    dicas = []\n    estrutura = []\n    execucoes = 0\n\n\n_NUMERO = re.compile(r\"-?\\d+(?:\\.\\d+)?\")\n_LETRAS = re.compile(r\"[^\\W\\d_]+\")\n\n\ndef _tokens(s, caixa):\n    t = _sem_acentos(str(s))\n    nums = _NUMERO.findall(t)\n    letras = \"\".join(_LETRAS.findall(_NUMERO.sub(\" \", t)))\n    return nums, (letras if caixa else letras.lower())\n\n\ndef _distancia(a, b, limite):\n    if abs(len(a) - len(b)) > limite:\n        return limite + 1\n    ant = list(range(len(b) + 1))\n    for i, ca in enumerate(a, 1):\n        atual = [i] + [0] * len(b)\n        menor = i\n        for j, cb in enumerate(b, 1):\n            atual[j] = min(ant[j] + 1, atual[j - 1] + 1, ant[j - 1] + (ca != cb))\n            menor = min(menor, atual[j])\n        if menor > limite:\n            return limite + 1\n        ant = atual\n    return ant[-1]\n\n\ndef _linha_parecida(esp, rec):\n    if _Leniencia.espacos:\n        a, b = _sem_acentos(str(esp)), _sem_acentos(str(rec))\n        return a == b if _Leniencia.caixa else a.lower() == b.lower()\n    ne, le = _tokens(esp, _Leniencia.caixa)\n    nr, lr = _tokens(rec, _Leniencia.caixa)\n    if ne != nr:\n        return False\n    if le == lr:\n        return True\n    limite = min(max(len(le), len(lr)) // 8, 3)\n    return _distancia(le, lr, limite) <= limite\n\n\ndef _saida_parecida(esp, rec):\n    e = [l for l in esp if l.strip()]\n    r = [l for l in rec if l.strip()]\n    if not r:\n        return False\n    if len(e) == len(r) and all(_linha_parecida(a, b) for a, b in zip(e, r)):\n        return True\n    return not _Leniencia.espacos and _linha_parecida(\" \".join(e), \" \".join(r))\n\n\ndef _nota_quase(esp, rec):\n    e = [l for l in esp if l.strip()]\n    r = [l for l in rec if l.strip()]\n    for a, b in zip(e, r):\n        if a != b:\n            p = _pista(a, b)\n            return f\"Passou! S\u00f3 um detalhe: o esperado era {_r(a)} e saiu {_r(b)}.\" + (f\" {p}\" if p else \"\")\n    return \"Passou! S\u00f3 um detalhe: as linhas em branco (ou as quebras de linha) ficaram um pouco diferentes do esperado.\"\n\n\ndef _canonico(s, caixa):\n    partes = re.findall(r\"-?\\d+(?:\\.\\d+)?|[^\\W\\d_]+\", _sem_acentos(str(s)))\n    return \" \" + \" \".join(partes if caixa else [x.lower() for x in partes]) + \" \"\n\n\ndef _contem_parecido(texto, trecho):\n    c = _canonico(trecho, _Leniencia.caixa)\n    return bool(c.strip()) and c in _canonico(texto, _Leniencia.caixa)\n\n\ndef _falha_estrutura(msg):\n    \"\"\"Checagem do \"jeito de resolver\": na corre\u00e7\u00e3o tranquila vira sugest\u00e3o (o teste continua).\"\"\"\n    if _Leniencia.ativa:\n        _Leniencia.estrutura.append(msg)\n        return\n    raise FalhaTeste(msg)\n\n\n_OBJ_PADRAO = re.compile(r\"<(?:__main__\\.)?([\\w.]+) object at 0x[0-9a-fA-F]+>\")\n\n\ndef _r(v, limite=120):\n    try:\n        s = repr(v)\n    except Exception:  # noqa: BLE001\n        s = f\"<{type(v).__name__}>\"\n    s = _OBJ_PADRAO.sub(lambda m: f\"<objeto {m.group(1)}>\", s)\n    return s if len(s) <= limite else s[: limite - 3] + \"...\"\n\n\ndef _prefixo(ctx):\n    return (ctx + \": \") if ctx else \"\"\n\n\nclass _Contexto:\n    codigo = \"\"\n    arvore = None\n    arquivos = None\n    banco = None\n    banco_arquivo = None\n    linguagem = \"python\"\n\n\n_CTX = _Contexto()\n\n\ndef rodar(entradas=None, semente=None, permitir_erro=False, nome_modulo=\"__main__\"):\n    \"\"\"Roda o c\u00f3digo do aluno do zero e devolve um Resultado.\"\"\"\n    _preparar_arquivos(_CTX.arquivos)\n    _preparar_banco(_CTX.banco, _CTX.banco_arquivo)\n    entradas = [str(x) for x in (entradas or [])]\n    _Leniencia.execucoes += 1\n    r = _executar(_CTX.codigo, entradas, semente, eco=False, nome_modulo=nome_modulo)\n    if entradas:\n        r.contexto = \"Com a entrada \" + _r(entradas[0]) if len(entradas) == 1 else \"Com as entradas \" + \", \".join(_r(x) for x in entradas)\n    if r.fim == \"entrada\":\n        if entradas:\n            raise FalhaTeste(\n                f\"{_prefixo(r.contexto)}seu programa pediu mais um input() \"\n                f\"(pergunta: {_r(r.prompt_pendente)}), mas o teste s\u00f3 tinha {len(entradas)} entrada(s).\"\n            )\n        raise FalhaTeste(\n            f\"Seu programa pediu um input() (pergunta: {_r(r.prompt_pendente)}), \"\n            \"mas neste exerc\u00edcio ele n\u00e3o deveria pedir nada ao usu\u00e1rio.\"\n        )\n    if r.fim == \"limite\":\n        raise FalhaTeste(f\"{_prefixo(r.contexto)}seu programa mostrou texto demais \u2014 parece um loop infinito.\")\n    if r.fim == \"tempo\":\n        raise FalhaTeste(f\"{_prefixo(r.contexto)}seu programa demorou demais e foi interrompido na linha \"\n                         f\"{r.linha_tempo}. Parece um loop infinito: a condi\u00e7\u00e3o do la\u00e7o muda em algum momento?\")\n    if r.fim == \"erro\" and not permitir_erro:\n        raise FalhaTeste(f\"{_prefixo(r.contexto)}seu c\u00f3digo deu erro:\\n{_resumo_erro(r.erro)}\")\n    if r.fim == \"exit\" and not permitir_erro:\n        pass\n    return r\n\n\ndef falhar(msg, esperado=None, recebido=None):\n    raise FalhaTeste(msg, esperado, recebido)\n\n\ndef verificar(condicao, msg):\n    if not condicao:\n        raise FalhaTeste(msg)\n\n\ndef saida_igual(r, esperado, contexto=None):\n    \"\"\"Compara a sa\u00edda inteira (ignora espa\u00e7os no fim das linhas e linhas vazias no final).\"\"\"\n    ctx = contexto if contexto is not None else getattr(r, \"contexto\", \"\")\n    rec_txt = r.saida if isinstance(r, Resultado) else str(r)\n    esp = _linhas(esperado) if isinstance(esperado, str) else [str(x) for x in esperado]\n    rec = _linhas(rec_txt)\n    if esp == rec:\n        return\n    if _Leniencia.ativa and _saida_parecida(esp, rec):\n        _Leniencia.dicas.append(_nota_quase(esp, rec))\n        return\n    esp_txt, rec_txt2 = \"\\n\".join(esp), \"\\n\".join(rec)\n    if not rec:\n        if isinstance(r, Resultado):\n            raise FalhaTeste(f\"{_prefixo(ctx)}seu programa n\u00e3o mostrou nada. Faltou um print()?\", esp_txt, \"\")\n        raise FalhaTeste(f\"{_prefixo(ctx)}nada foi mostrado na tela. Faltou um print()?\", esp_txt, \"\")\n    # na corre\u00e7\u00e3o tranquila as linhas em branco n\u00e3o contam: compara s\u00f3 as linhas com conte\u00fado\n    E = [l for l in esp if l.strip()] if _Leniencia.ativa else esp\n    R = [(l, i) for i, l in enumerate(rec) if l.strip() or not _Leniencia.ativa]\n    for a, (b, i) in zip(E, R):\n        if a != b and not (_Leniencia.ativa and _linha_parecida(a, b)):\n            pista = _pista(a, b)\n            msg = f\"{_prefixo(ctx)}a linha {i + 1} da sa\u00edda est\u00e1 diferente.\\n  esperado: {_r(a)}\\n  recebido: {_r(b)}\"\n            if pista:\n                msg += \"\\n\" + pista\n            raise FalhaTeste(msg, esp_txt, rec_txt2)\n    if len(R) < len(E):\n        falta = len(E) - len(R)\n        qtd = \"uma linha\" if falta == 1 else f\"{falta} linhas\"\n        raise FalhaTeste(f\"{_prefixo(ctx)}faltou {qtd} na sa\u00edda. A pr\u00f3xima esperada era: {_r(E[len(R)])}\",\n                         esp_txt, rec_txt2)\n    raise FalhaTeste(f\"{_prefixo(ctx)}sua sa\u00edda tem linhas a mais. A primeira que sobrou foi: {_r(R[len(E)][0])}\",\n                     esp_txt, rec_txt2)\n\n\ndef saida_contem(r, trecho, msg=None):\n    rec = \"\\n\".join(_linhas(r.saida if isinstance(r, Resultado) else str(r)))\n    if trecho not in rec and _Leniencia.ativa and _contem_parecido(rec, trecho):\n        _Leniencia.dicas.append(f\"Passou! S\u00f3 um detalhe: o esperado era ver exatamente {_r(trecho)} na sa\u00edda.\")\n        return\n    if trecho not in rec:\n        ctx = getattr(r, \"contexto\", \"\")\n        raise FalhaTeste(msg or f\"{_prefixo(ctx)}esperava ver {_r(trecho)} na sa\u00edda, mas n\u00e3o apareceu.\",\n                         trecho, rec)\n\n\ndef ultima_linha(r):\n    ls = _linhas(r.saida)\n    if not ls:\n        raise FalhaTeste(f\"{_prefixo(getattr(r, 'contexto', ''))}seu programa n\u00e3o mostrou nada. Faltou um print()?\")\n    return ls[-1]\n\n\n_NOMES_TIPO = {\n    int: \"int (n\u00famero inteiro)\", float: \"float (n\u00famero decimal)\", str: \"str (texto)\",\n    bool: \"bool (True/False)\", list: \"list (lista)\", dict: \"dict (dicion\u00e1rio)\",\n    tuple: \"tuple (tupla)\", set: \"set (conjunto)\",\n}\n\n\ndef _nome_tipo(t):\n    if isinstance(t, tuple):\n        return \" ou \".join(_nome_tipo(x) for x in t)\n    return _NOMES_TIPO.get(t, getattr(t, \"__name__\", str(t)))\n\n\ndef _e_tipo(v, tipo):\n    tipos = tipo if isinstance(tipo, tuple) else (tipo,)\n    if isinstance(v, bool) and bool not in tipos:\n        return False\n    return isinstance(v, tipos)\n\n\ndef pegar_var(r, nome, tipo=None):\n    if nome not in r.ns:\n        raise FalhaTeste(f\"N\u00e3o encontrei a vari\u00e1vel `{nome}`. Crie uma vari\u00e1vel com exatamente esse nome.\")\n    v = r.ns[nome]\n    if tipo is not None and not _e_tipo(v, tipo):\n        raise FalhaTeste(f\"A vari\u00e1vel `{nome}` deveria ser {_nome_tipo(tipo)}, mas \u00e9 \"\n                         f\"{type(v).__name__} (valor: {_r(v)}).\")\n    return v\n\n\ndef pegar_func(r, nome):\n    if nome not in r.ns:\n        raise FalhaTeste(f\"N\u00e3o encontrei a fun\u00e7\u00e3o `{nome}`. Defina com def {nome}(...): \u2014 com esse nome exato.\")\n    f = r.ns[nome]\n    if not callable(f):\n        raise FalhaTeste(f\"`{nome}` existe, mas n\u00e3o \u00e9 uma fun\u00e7\u00e3o (\u00e9 {type(f).__name__}).\")\n    return f\n\n\ndef pegar_classe(r, nome):\n    if nome not in r.ns:\n        raise FalhaTeste(f\"N\u00e3o encontrei a classe `{nome}`. Crie com class {nome}: \u2014 com esse nome exato.\")\n    c = r.ns[nome]\n    if not isinstance(c, type):\n        raise FalhaTeste(f\"`{nome}` existe, mas n\u00e3o \u00e9 uma classe.\")\n    return c\n\n\ndef atributo(obj, nome):\n    if not hasattr(obj, nome):\n        raise FalhaTeste(f\"O objeto {type(obj).__name__} n\u00e3o tem o atributo `{nome}`. \"\n                         f\"Voc\u00ea guardou com self.{nome} = ... ?\")\n    return getattr(obj, nome)\n\n\ndef _desc_chamada(f, args, kwargs):\n    nome = getattr(f, \"__name__\", \"fun\u00e7\u00e3o\")\n    partes = [_r(a, 60) for a in args] + [f\"{k}={_r(v, 60)}\" for k, v in kwargs.items()]\n    return f\"{nome}({', '.join(partes)})\"\n\n\ndef _chamar(f, args, kwargs, desc=None):\n    def _d():\n        return desc or _desc_chamada(f, args, kwargs)\n\n    out = _Saida()\n    velhos = (sys.stdout, sys.stderr, builtins.input)\n\n    def _input(prompt=\"\"):\n        raise _SinalInputProibido()\n\n    sys.stdout = out\n    sys.stderr = out\n    builtins.input = _input\n    limite_rec = sys.getrecursionlimit()\n    try:\n        v = f(*args, **kwargs)\n    except FalhaTeste:\n        raise\n    except _SinalInputProibido:\n        raise FalhaTeste(f\"Ao chamar {_d()}, a fun\u00e7\u00e3o pediu input(). Aqui ela deve usar s\u00f3 os \"\n                         \"par\u00e2metros que recebe.\") from None\n    except _SinalSaidaDemais:\n        raise FalhaTeste(f\"Ao chamar {_d()}, a fun\u00e7\u00e3o mostrou texto demais \u2014 loop infinito?\") from None\n    except _SinalTempo as t:\n        raise FalhaTeste(f\"Ao chamar {_d()}, a fun\u00e7\u00e3o demorou demais e foi interrompida na linha {t.linha}. \"\n                         \"Parece um loop infinito (ou uma solu\u00e7\u00e3o lenta demais).\") from None\n    except RecursionError:\n        raise FalhaTeste(f\"Ao chamar {_d()}: RecursionError \u2014 a fun\u00e7\u00e3o chamou a si mesma sem parar. \"\n                         \"Falta um caso base?\") from None\n    except BaseException as e:  # noqa: BLE001\n        raise FalhaTeste(f\"Ao chamar {_d()} aconteceu um erro:\\n{_resumo_erro(e)}\") from None\n    finally:\n        sys.stdout, sys.stderr, builtins.input = velhos\n        sys.setrecursionlimit(limite_rec)\n    return v, out.getvalue()\n\n\ndef chamar(f, *args, **kwargs):\n    return _chamar(f, args, kwargs)[0]\n\n\ndef chamar_com_saida(f, *args, **kwargs):\n    return _chamar(f, args, kwargs)\n\n\ndef _numero(v):\n    return isinstance(v, (int, float)) and not isinstance(v, bool)\n\n\ndef _iguais(a, b):\n    if _numero(a) and _numero(b) and (isinstance(a, float) or isinstance(b, float)):\n        return math.isclose(a, b, rel_tol=1e-9, abs_tol=1e-9)\n    if isinstance(a, bool) != isinstance(b, bool):\n        return False\n    if type(a) is not type(b) and not (_numero(a) and _numero(b)):\n        return False\n    if isinstance(a, (list, tuple)):\n        return len(a) == len(b) and all(_iguais(x, y) for x, y in zip(a, b))\n    if isinstance(a, dict):\n        return a.keys() == b.keys() and all(_iguais(a[k], b[k]) for k in a)\n    try:\n        return bool(a == b)\n    except Exception:  # noqa: BLE001\n        return False\n\n\ndef _onde_difere(obtido, esperado):\n    \"\"\"Aponta a primeira diferen\u00e7a em listas/tuplas/dicion\u00e1rios (mensagens longas escondem o erro).\"\"\"\n    if isinstance(esperado, (list, tuple)) and isinstance(obtido, (list, tuple)):\n        if len(obtido) != len(esperado):\n            return f\"\\nTamanho esperado: {len(esperado)} itens; veio com {len(obtido)}.\"\n        for i, (x, y) in enumerate(zip(obtido, esperado)):\n            if not _iguais(x, y):\n                return f\"\\nPrimeira diferen\u00e7a na posi\u00e7\u00e3o [{i}]: esperado {_r(y, 80)}, veio {_r(x, 80)}.\"\n    if isinstance(esperado, dict) and isinstance(obtido, dict):\n        faltam = [k for k in esperado if k not in obtido]\n        sobram = [k for k in obtido if k not in esperado]\n        if faltam:\n            return f\"\\nFaltou a chave {_r(faltam[0], 60)}\" + (f\" (e mais {len(faltam) - 1})\" if len(faltam) > 1 else \"\") + \".\"\n        if sobram:\n            return f\"\\nSobrou a chave {_r(sobram[0], 60)}\" + (f\" (e mais {len(sobram) - 1})\" if len(sobram) > 1 else \"\") + \".\"\n        for k in esperado:\n            if not _iguais(obtido[k], esperado[k]):\n                return f\"\\nNa chave {_r(k, 60)}: esperado {_r(esperado[k], 80)}, veio {_r(obtido[k], 80)}.\"\n    return \"\"\n\n\ndef igual(obtido, esperado, desc=\"O resultado\"):\n    if _iguais(obtido, esperado):\n        return\n    dica = \"\"\n    if obtido is None and esperado is not None:\n        dica = \"\\nVeio None: faltou o return? (print() s\u00f3 mostra na tela; return devolve o valor.)\"\n    elif _numero(esperado) and isinstance(obtido, str):\n        dica = \"\\nVeio um texto, mas era para ser um n\u00famero. (Faltou int() ou float()?)\"\n    elif isinstance(esperado, str) and _numero(obtido):\n        dica = \"\\nVeio um n\u00famero, mas era para ser um texto (str).\"\n    elif type(obtido) is not type(esperado) and not (_numero(obtido) and _numero(esperado)):\n        dica = f\"\\nO tipo esperado era {type(esperado).__name__}, mas veio {type(obtido).__name__}.\"\n    else:\n        dica = _onde_difere(obtido, esperado)\n    raise FalhaTeste(f\"{desc} deveria ser {_r(esperado)}, mas foi {_r(obtido)}.{dica}\", _r(esperado, 400), _r(obtido, 400))\n\n\n# --- an\u00e1lise do c\u00f3digo (AST) ------------------------------------------------\n_NOMES_NOS = {\n    \"For\": \"um la\u00e7o for\", \"While\": \"um la\u00e7o while\", \"If\": \"um if\", \"FunctionDef\": \"uma fun\u00e7\u00e3o (def)\",\n    \"Return\": \"return\", \"ListComp\": \"uma list comprehension\", \"DictComp\": \"uma dict comprehension\",\n    \"SetComp\": \"uma set comprehension\", \"GeneratorExp\": \"uma express\u00e3o geradora\",\n    \"Lambda\": \"uma fun\u00e7\u00e3o lambda\", \"Try\": \"try/except\", \"ClassDef\": \"uma classe (class)\",\n    \"With\": \"o comando with\", \"Yield\": \"yield\", \"YieldFrom\": \"yield from\", \"JoinedStr\": \"uma f-string\",\n    \"Break\": \"break\", \"Continue\": \"continue\", \"Match\": \"match/case\", \"AugAssign\": \"um operador como += ou -=\",\n    \"Import\": \"import\", \"ImportFrom\": \"from ... import\", \"Raise\": \"raise\", \"Assert\": \"assert\",\n    \"Global\": \"global\", \"BoolOp\": \"and/or\", \"Compare\": \"uma compara\u00e7\u00e3o\", \"Subscript\": \"colchetes [ ]\",\n    \"Slice\": \"fatiamento [in\u00edcio:fim]\", \"Dict\": \"um dicion\u00e1rio { }\", \"List\": \"uma lista [ ]\",\n    \"Set\": \"um conjunto { }\", \"Tuple\": \"uma tupla\", \"IfExp\": \"um if de uma linha (x if cond else y)\",\n    \"Starred\": \"desempacotamento com *\", \"Assign\": \"uma atribui\u00e7\u00e3o (=)\", \"Call\": \"uma chamada de fun\u00e7\u00e3o\",\n}\n\n_OPERADORES = {\n    \"+\": ast.Add, \"-\": ast.Sub, \"*\": ast.Mult, \"/\": ast.Div, \"//\": ast.FloorDiv,\n    \"%\": ast.Mod, \"**\": ast.Pow,\n}\n\n\ndef _classes_no(nomes):\n    if isinstance(nomes, str):\n        nomes = [nomes]\n    return tuple(getattr(ast, n) for n in nomes if hasattr(ast, n))\n\n\ndef conta_no(nome):\n    classes = _classes_no(nome)\n    if not classes:\n        return 0\n    return sum(1 for n in ast.walk(_CTX.arvore) if isinstance(n, classes))\n\n\ndef usa(nome, msg=None):\n    if conta_no(nome) == 0:\n        primeiro = nome if isinstance(nome, str) else nome[0]\n        _falha_estrutura(msg or f\"Este exerc\u00edcio pede que voc\u00ea use {_NOMES_NOS.get(primeiro, primeiro)}.\")\n\n\ndef nao_usa(nome, msg=None):\n    if conta_no(nome) > 0:\n        primeiro = nome if isinstance(nome, str) else nome[0]\n        _falha_estrutura(msg or f\"Neste exerc\u00edcio, n\u00e3o use {_NOMES_NOS.get(primeiro, primeiro)}.\")\n\n\ndef _nome_chamada(no):\n    f = no.func\n    if isinstance(f, ast.Name):\n        return f.id\n    if isinstance(f, ast.Attribute):\n        return f.attr\n    return None\n\n\ndef conta_chamadas(nome):\n    return sum(1 for n in ast.walk(_CTX.arvore) if isinstance(n, ast.Call) and _nome_chamada(n) == nome)\n\n\ndef usa_chamada(nome, msg=None):\n    if conta_chamadas(nome) == 0:\n        _falha_estrutura(msg or f\"Este exerc\u00edcio pede que voc\u00ea use {nome}(...).\")\n\n\ndef nao_usa_chamada(nome, msg=None):\n    if conta_chamadas(nome) > 0:\n        _falha_estrutura(msg or f\"Neste exerc\u00edcio, resolva sem usar {nome}(...).\")\n\n\ndef usa_operador(simbolo, msg=None):\n    cls = _OPERADORES[simbolo]\n    for n in ast.walk(_CTX.arvore):\n        if isinstance(n, (ast.BinOp, ast.AugAssign)) and isinstance(n.op, cls):\n            return\n    _falha_estrutura(msg or f\"Este exerc\u00edcio pede que voc\u00ea use o operador {simbolo}.\")\n\n\ndef usa_fstring(msg=None):\n    usa(\"JoinedStr\", msg or \"Este exerc\u00edcio pede que voc\u00ea use uma f-string (f\\\"...{variavel}...\\\").\")\n\n\ndef funcao_definida(nome):\n    for n in ast.walk(_CTX.arvore):\n        if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)) and n.name == nome:\n            return n\n    return None\n\n\ndef e_recursiva(nome, msg=None):\n    fn = funcao_definida(nome)\n    if fn is None:\n        raise FalhaTeste(f\"N\u00e3o encontrei a fun\u00e7\u00e3o `{nome}`.\")\n    for n in ast.walk(fn):\n        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id == nome:\n            return\n    raise FalhaTeste(msg or f\"A fun\u00e7\u00e3o `{nome}` precisa ser recursiva: ela deve chamar {nome}(...) dentro dela mesma.\")\n\n\ndef texto_do_codigo():\n    return _CTX.codigo\n\n\n# --- arquivos (para as aulas de arquivos) ----------------------------------\ndef criar_arquivo(nome, conteudo):\n    with open(nome, \"w\", encoding=\"utf-8\") as f:\n        f.write(conteudo)\n\n\ndef ler_arquivo(nome):\n    if not os.path.exists(nome):\n        raise FalhaTeste(f\"O arquivo {_r(nome)} n\u00e3o foi criado.\")\n    with open(nome, encoding=\"utf-8\") as f:\n        return f.read()\n\n\ndef apagar_arquivo(nome):\n    try:\n        os.remove(nome)\n    except FileNotFoundError:\n        pass\n\n\n# ----------------------------------------------------------------------------\n# miniweb: um mini framework web (parecido com Flask/FastAPI) para as aulas de back-end\n# ----------------------------------------------------------------------------\nMINIWEB_FONTE = r'''\n\"\"\"miniweb \u2014 um mini framework web para aprender back-end.\n\nFunciona como os frameworks de verdade (Flask, FastAPI): voc\u00ea cria um App,\nregistra rotas com decoradores e testa com um cliente, tudo sem rede.\n\"\"\"\nimport json as _json\nimport re as _re\nfrom http import HTTPStatus as _Status\nfrom urllib.parse import urlsplit as _urlsplit, parse_qs as _parse_qs, unquote as _unquote\n\n__all__ = [\"App\", \"Requisicao\", \"Resposta\", \"ErroHTTP\", \"abortar\", \"Cliente\"]\n\n\nclass ErroHTTP(Exception):\n    \"\"\"Erro que vira uma resposta HTTP (ex.: 404 Not Found).\"\"\"\n\n    def __init__(self, status, mensagem=None):\n        self.status = int(status)\n        try:\n            padrao = _Status(self.status).phrase\n        except ValueError:\n            padrao = \"Erro\"\n        self.mensagem = mensagem or padrao\n        super().__init__(f\"{self.status} {self.mensagem}\")\n\n\ndef abortar(status, mensagem=None):\n    \"\"\"Interrompe a rota e responde com esse status: abortar(404, \"Jogador n\u00e3o encontrado\").\"\"\"\n    raise ErroHTTP(status, mensagem)\n\n\nclass Requisicao:\n    \"\"\"O pedido que chegou: m\u00e9todo, caminho, par\u00e2metros, corpo JSON e cabe\u00e7alhos.\"\"\"\n\n    def __init__(self, metodo, caminho, consulta=None, json=None, cabecalhos=None, params=None):\n        self.metodo = metodo\n        self.caminho = caminho\n        self.consulta = consulta or {}\n        self.json = json\n        self.cabecalhos = {str(k).lower(): v for k, v in (cabecalhos or {}).items()}\n        self.params = params or {}\n        self.dados = {}\n\n    def cabecalho(self, nome, padrao=None):\n        return self.cabecalhos.get(str(nome).lower(), padrao)\n\n    def __repr__(self):\n        return f\"<Requisicao {self.metodo} {self.caminho}>\"\n\n\nclass Resposta:\n    \"\"\"O que o servidor devolve: status, corpo (texto ou JSON) e cabe\u00e7alhos.\"\"\"\n\n    def __init__(self, corpo=None, status=200, cabecalhos=None):\n        self.status = int(status)\n        self.cabecalhos = dict(cabecalhos or {})\n        if isinstance(corpo, (dict, list)):\n            self.texto = _json.dumps(corpo, ensure_ascii=False)\n            self.cabecalhos.setdefault(\"Content-Type\", \"application/json\")\n        elif corpo is None:\n            self.texto = \"\"\n        else:\n            self.texto = str(corpo)\n            self.cabecalhos.setdefault(\"Content-Type\", \"text/plain\")\n\n    def json(self):\n        return _json.loads(self.texto) if self.texto else None\n\n    @property\n    def ok(self):\n        return 200 <= self.status < 300\n\n    def __repr__(self):\n        return f\"<Resposta {self.status} {self.texto[:60]}>\"\n\n\n_CONVERSORES = {\"int\": (r\"-?\\d+\", int), \"str\": (r\"[^/]+\", str), \"float\": (r\"-?\\d+(?:\\.\\d+)?\", float)}\n\n\nclass _Rota:\n    def __init__(self, metodo, modelo, funcao):\n        self.metodo, self.modelo, self.funcao = metodo, modelo, funcao\n        partes, self.conversores, pos = [], {}, 0\n        for m in _re.finditer(r\"<(?:(\\w+):)?(\\w+)>\", modelo):\n            partes.append(_re.escape(modelo[pos:m.start()]))\n            tipo = m.group(1) or \"str\"\n            if tipo not in _CONVERSORES:\n                raise ValueError(f\"tipo de par\u00e2metro desconhecido: {tipo}\")\n            regex, conv = _CONVERSORES[tipo]\n            partes.append(f\"(?P<{m.group(2)}>{regex})\")\n            self.conversores[m.group(2)] = conv\n            pos = m.end()\n        partes.append(_re.escape(modelo[pos:]))\n        self.regex = _re.compile(\"^\" + \"\".join(partes) + \"/?$\")\n\n    def casa(self, caminho):\n        m = self.regex.match(caminho)\n        if not m:\n            return None\n        return {k: self.conversores[k](v) for k, v in m.groupdict().items()}\n\n\nclass App:\n    \"\"\"Um aplicativo web: rotas + middlewares. Use app.cliente() para fazer requisi\u00e7\u00f5es de teste.\"\"\"\n\n    def __init__(self, nome=\"app\", depurar=True):\n        self.nome = nome\n        self.depurar = depurar\n        self.rotas = []\n        self._antes = []\n        self._depois = []\n\n    def rota(self, caminho, metodos=(\"GET\",)):\n        def registrar(funcao):\n            for metodo in metodos:\n                self.rotas.append(_Rota(str(metodo).upper(), caminho, funcao))\n            return funcao\n        return registrar\n\n    def get(self, caminho):\n        return self.rota(caminho, [\"GET\"])\n\n    def post(self, caminho):\n        return self.rota(caminho, [\"POST\"])\n\n    def put(self, caminho):\n        return self.rota(caminho, [\"PUT\"])\n\n    def patch(self, caminho):\n        return self.rota(caminho, [\"PATCH\"])\n\n    def delete(self, caminho):\n        return self.rota(caminho, [\"DELETE\"])\n\n    def antes(self, funcao):\n        \"\"\"Roda antes de toda rota. Se devolver algo, isso vira a resposta (e a rota n\u00e3o roda).\"\"\"\n        self._antes.append(funcao)\n        return funcao\n\n    def depois(self, funcao):\n        \"\"\"Roda depois de toda rota: recebe (req, resposta) e pode devolver outra resposta.\"\"\"\n        self._depois.append(funcao)\n        return funcao\n\n    @staticmethod\n    def _resposta(r):\n        if isinstance(r, Resposta):\n            return r\n        if isinstance(r, tuple):\n            return Resposta(r[0], r[1] if len(r) > 1 else 200, r[2] if len(r) > 2 else None)\n        return Resposta(r, 200)\n\n    def _finalizar(self, req, resp):\n        for f in self._depois:\n            outra = f(req, resp)\n            if outra is not None:\n                resp = self._resposta(outra)\n        return resp\n\n    def processar(self, metodo, url, json=None, cabecalhos=None):\n        metodo = str(metodo).upper()\n        partes = _urlsplit(url)\n        caminho = _unquote(partes.path or \"/\")\n        consulta = {k: (v[0] if len(v) == 1 else v) for k, v in _parse_qs(partes.query).items()}\n        req = Requisicao(metodo, caminho, consulta, json, cabecalhos)\n        achou_caminho = False\n        for rota in self.rotas:\n            params = rota.casa(caminho)\n            if params is None:\n                continue\n            achou_caminho = True\n            if rota.metodo != metodo:\n                continue\n            req.params = params\n            try:\n                for f in self._antes:\n                    r = f(req)\n                    if r is not None:\n                        return self._finalizar(req, self._resposta(r))\n                return self._finalizar(req, self._resposta(rota.funcao(req, **params)))\n            except ErroHTTP as e:\n                return self._finalizar(req, Resposta({\"erro\": e.mensagem}, e.status))\n            except Exception:\n                if self.depurar:\n                    raise\n                return self._finalizar(req, Resposta({\"erro\": \"Erro interno do servidor\"}, 500))\n        if achou_caminho:\n            return self._finalizar(req, Resposta({\"erro\": \"M\u00e9todo n\u00e3o permitido\"}, 405))\n        return self._finalizar(req, Resposta({\"erro\": \"Rota n\u00e3o encontrada\"}, 404))\n\n    def cliente(self, cabecalhos=None):\n        return Cliente(self, cabecalhos)\n\n\nclass Cliente:\n    \"\"\"Faz requisi\u00e7\u00f5es de teste para o seu App (como o test client do Flask).\"\"\"\n\n    def __init__(self, app, cabecalhos=None):\n        self.app = app\n        self.cabecalhos = dict(cabecalhos or {})\n\n    def requisitar(self, metodo, url, json=None, cabecalhos=None):\n        cab = dict(self.cabecalhos)\n        cab.update(cabecalhos or {})\n        return self.app.processar(metodo, url, json=json, cabecalhos=cab)\n\n    def get(self, url, **kw):\n        return self.requisitar(\"GET\", url, **kw)\n\n    def post(self, url, json=None, **kw):\n        return self.requisitar(\"POST\", url, json=json, **kw)\n\n    def put(self, url, json=None, **kw):\n        return self.requisitar(\"PUT\", url, json=json, **kw)\n\n    def patch(self, url, json=None, **kw):\n        return self.requisitar(\"PATCH\", url, json=json, **kw)\n\n    def delete(self, url, **kw):\n        return self.requisitar(\"DELETE\", url, **kw)\n'''\n\n\ndef _instalar_miniweb():\n    import types\n    mod = types.ModuleType(\"miniweb\")\n    mod.__file__ = \"miniweb.py\"\n    exec(compile(MINIWEB_FONTE, \"miniweb.py\", \"exec\"), mod.__dict__)\n    sys.modules[\"miniweb\"] = mod\n    return mod\n\n\n_instalar_miniweb()\n\n\n# ----------------------------------------------------------------------------\n# Banco de dados (SQLite) \u2014 aulas de SQL puro e de Python + SQLite\n# ----------------------------------------------------------------------------\nimport sqlite3  # noqa: E402\nimport logging  # noqa: E402\nimport unittest  # noqa: E402\n\n\nclass ErroSQL(Exception):\n    def __init__(self, erro, trecho, indice):\n        super().__init__(str(erro))\n        self.erro = erro\n        self.trecho = trecho\n        self.indice = indice\n\n\ndef _dividir_sql(texto):\n    \"\"\"Separa comandos SQL por ';' (ignorando ';' dentro de aspas e coment\u00e1rios).\"\"\"\n    partes, atual, aspas, i, n = [], [], None, 0, len(texto)\n    while i < n:\n        c = texto[i]\n        if aspas:\n            atual.append(c)\n            if c == aspas:\n                if i + 1 < n and texto[i + 1] == aspas:\n                    atual.append(texto[i + 1])\n                    i += 1\n                else:\n                    aspas = None\n        elif c in (\"'\", '\"'):\n            aspas = c\n            atual.append(c)\n        elif texto.startswith(\"--\", i):\n            fim = texto.find(\"\\n\", i)\n            i = n if fim == -1 else fim\n            continue\n        elif texto.startswith(\"/*\", i):\n            fim = texto.find(\"*/\", i + 2)\n            i = n if fim == -1 else fim + 2\n            continue\n        elif c == \";\":\n            s = \"\".join(atual).strip()\n            if s:\n                partes.append(s)\n            atual = []\n        else:\n            atual.append(c)\n        i += 1\n    s = \"\".join(atual).strip()\n    if s:\n        partes.append(s)\n    return partes\n\n\ndef _novo_banco(semente_sql=None, caminho=\":memory:\", segundos=4.0):\n    con = sqlite3.connect(caminho)\n    con.execute(\"PRAGMA foreign_keys = ON\")\n    prazo = time.perf_counter() + segundos\n    con.set_progress_handler(lambda: 1 if time.perf_counter() > prazo else 0, 20000)\n    if semente_sql:\n        con.executescript(semente_sql)\n        con.commit()\n    return con\n\n\ndef _preparar_banco(semente_sql, arquivo):\n    \"\"\"Cria (do zero) o arquivo de banco usado por uma aula de Python + SQLite.\"\"\"\n    if not semente_sql or not arquivo:\n        return\n    try:\n        os.remove(arquivo)\n    except FileNotFoundError:\n        pass\n    con = sqlite3.connect(arquivo)\n    con.executescript(semente_sql)\n    con.commit()\n    con.close()\n\n\ndef _executar_sql(codigo, semente_sql=None, limite=200, segundos=4.0):\n    \"\"\"Roda o SQL do aluno num banco novo. Devolve (conex\u00e3o, blocos).\"\"\"\n    con = _novo_banco(semente_sql, segundos=segundos)\n    blocos = []\n    for i, trecho in enumerate(_dividir_sql(codigo)):\n        try:\n            cur = con.execute(trecho)\n            if cur.description:\n                colunas = [d[0] for d in cur.description]\n                linhas = cur.fetchall()\n                blocos.append({\"sql\": trecho, \"colunas\": colunas, \"linhas\": [list(l) for l in linhas[:limite]],\n                               \"total\": len(linhas)})\n            else:\n                blocos.append({\"sql\": trecho, \"afetadas\": cur.rowcount if cur.rowcount >= 0 else None})\n        except sqlite3.Error as e:\n            raise ErroSQL(e, trecho, i) from None\n    con.commit()\n    return con, blocos\n\n\ndef _explicar_sql(e):\n    m = str(e).lower()\n    if \"interrupted\" in m:\n        return \"A consulta demorou demais e foi interrompida. Tem alguma repeti\u00e7\u00e3o sem fim (por exemplo, uma recurs\u00e3o)?\"\n    if \"no such table\" in m:\n        return \"Essa tabela n\u00e3o existe. Confira o nome (as tabelas desta aula est\u00e3o listadas na li\u00e7\u00e3o).\"\n    if \"no such column\" in m:\n        return (\"Essa coluna n\u00e3o existe. Confira o nome \u2014 ou, se era um texto, ponha entre aspas simples: \"\n                \"'Ana'. Aspas duplas s\u00e3o para nomes de colunas.\")\n    if \"syntax error\" in m:\n        return (\"Erro de escrita no SQL perto do trecho indicado. Confira v\u00edrgulas, par\u00eanteses, aspas e a ordem das partes: \"\n                \"SELECT \u2026 FROM \u2026 JOIN \u2026 WHERE \u2026 GROUP BY \u2026 HAVING \u2026 ORDER BY \u2026 LIMIT.\")\n    if \"incomplete input\" in m:\n        return \"O comando ficou incompleto: faltou fechar aspas ou par\u00eanteses?\"\n    if \"unique constraint failed\" in m:\n        return \"Esse valor j\u00e1 existe numa coluna que n\u00e3o aceita repetidos (UNIQUE ou PRIMARY KEY).\"\n    if \"not null constraint failed\" in m:\n        return \"Faltou preencher uma coluna obrigat\u00f3ria (NOT NULL).\"\n    if \"foreign key constraint failed\" in m:\n        return \"A chave estrangeira aponta para um registro que n\u00e3o existe (ou algo ainda depende deste registro).\"\n    if \"check constraint failed\" in m:\n        return \"O valor n\u00e3o passou na regra CHECK da tabela.\"\n    if \"misuse of aggregate\" in m:\n        return \"Fun\u00e7\u00e3o de agrega\u00e7\u00e3o (COUNT, SUM...) no lugar errado. Para filtrar grupos, use HAVING em vez de WHERE.\"\n    if \"ambiguous column name\" in m:\n        return \"Essa coluna existe em mais de uma tabela do JOIN. Escreva tabela.coluna para dizer qual \u00e9.\"\n    if \"already exists\" in m:\n        return \"Essa tabela j\u00e1 existe. Use outro nome ou CREATE TABLE IF NOT EXISTS.\"\n    if \"values for\" in m and \"columns\" in m:\n        return \"A quantidade de valores n\u00e3o bate com a quantidade de colunas do INSERT.\"\n    if \"no such function\" in m:\n        return \"Essa fun\u00e7\u00e3o n\u00e3o existe no SQLite. Confira o nome (COUNT, SUM, AVG, MIN, MAX, ROUND, LOWER, UPPER...).\"\n    if \"datatype mismatch\" in m:\n        return \"Tipo de dado errado para essa coluna.\"\n    if \"incorrect number of bindings\" in m:\n        return (\"A quantidade de ? no SQL n\u00e3o bate com a quantidade de valores passados. \"\n                \"Um valor s\u00f3 vai numa tupla com v\u00edrgula: con.execute(sql, (nome,)).\")\n    if \"closed database\" in m:\n        return \"A conex\u00e3o j\u00e1 foi fechada com close(). Feche s\u00f3 quando terminar de usar o banco.\"\n    if \"unsupported type\" in m or \"binding parameter\" in m or \"type 'dict' is not supported\" in m:\n        return \"Os valores dos ? precisam ir numa tupla ou lista de textos/n\u00fameros: con.execute(sql, (valor,)).\"\n    if \"unable to open database\" in m:\n        return \"N\u00e3o consegui abrir o arquivo do banco. Confira o nome do arquivo.\"\n    if \"database is locked\" in m:\n        return \"O banco est\u00e1 ocupado por outra conex\u00e3o. Fa\u00e7a commit() ou feche a outra conex\u00e3o.\"\n    return \"O banco de dados n\u00e3o aceitou esse comando.\"\n\n\ndef _info_erro_sql(err):\n    e = err.erro if isinstance(err, ErroSQL) else err\n    trecho = err.trecho if isinstance(err, ErroSQL) else \"\"\n    texto = f\"{type(e).__name__}: {e}\"\n    if trecho:\n        texto = f\"No comando {err.indice + 1}:\\n{trecho}\\n\\n{texto}\"\n    return {\"tipo\": type(e).__name__, \"texto\": texto, \"linha\": None, \"dica\": _explicar_sql(e)}\n\n\nclass ResultadoSQL:\n    def __init__(self, con, blocos):\n        self.con = con\n        self.blocos = blocos\n        selects = [b for b in blocos if \"colunas\" in b]\n        self.ultimo = selects[-1] if selects else None\n\n    @property\n    def colunas(self):\n        return self.ultimo[\"colunas\"] if self.ultimo else []\n\n    @property\n    def linhas(self):\n        return [tuple(l) for l in self.ultimo[\"linhas\"]] if self.ultimo else []\n\n\ndef rodar_sql(banco=None):\n    \"\"\"Roda o SQL do aluno num banco novo com os dados da aula (ou com outro `banco`).\"\"\"\n    semente = _CTX.banco if banco is None else banco\n    try:\n        con, blocos = _executar_sql(_CTX.codigo, semente, limite=100000)\n    except ErroSQL as e:\n        info = _info_erro_sql(e)\n        raise FalhaTeste(f\"O SQL deu erro:\\n{info['texto']}\\n\u2192 {info['dica']}\") from None\n    except sqlite3.Error as e:\n        raise FalhaTeste(f\"Erro ao preparar o banco do teste: {e}\") from None\n    if not blocos:\n        raise FalhaTeste(\"N\u00e3o achei nenhum comando SQL. Escreva a consulta no editor (e termine com ;).\")\n    return ResultadoSQL(con, blocos)\n\n\ndef consulta(sql, banco=None):\n    \"\"\"Roda um SQL de refer\u00eancia num banco novo com os dados da aula. Devolve as linhas (lista de tuplas).\"\"\"\n    con = _novo_banco(_CTX.banco if banco is None else banco)\n    try:\n        return [tuple(l) for l in con.execute(sql).fetchall()]\n    finally:\n        con.close()\n\n\ndef conectar_banco(banco=None):\n    \"\"\"Conex\u00e3o SQLite em mem\u00f3ria j\u00e1 com os dados da aula (para testar fun\u00e7\u00f5es que recebem uma conex\u00e3o).\"\"\"\n    return _novo_banco(_CTX.banco if banco is None else banco)\n\n\ndef tabela(con, nome, ordem=None):\n    sql = f'SELECT * FROM \"{nome}\"' + (f\" ORDER BY {ordem}\" if ordem else \"\")\n    try:\n        return [tuple(l) for l in con.execute(sql).fetchall()]\n    except sqlite3.Error as e:\n        raise FalhaTeste(f\"N\u00e3o consegui ler a tabela {nome}: {e}\") from None\n\n\ndef colunas_da_tabela(con, nome):\n    return [r[1] for r in con.execute(f'PRAGMA table_info(\"{nome}\")').fetchall()]\n\n\ndef _tabela_txt(linhas, limite=8):\n    if not linhas:\n        return \"(nenhuma linha)\"\n    txt = \"\\n\".join(_r(tuple(l), 100) for l in linhas[:limite])\n    if len(linhas) > limite:\n        txt += f\"\\n... (+{len(linhas) - limite} linhas)\"\n    return txt\n\n\ndef linhas_iguais(obtidas, esperadas, ordem=True, desc=\"O resultado da consulta\"):\n    \"\"\"Compara linhas (listas de tuplas). ordem=False ignora a ordem das linhas.\"\"\"\n    if isinstance(obtidas, ResultadoSQL):\n        obtidas = obtidas.linhas\n    ob = [tuple(x) for x in obtidas]\n    es = [tuple(x) for x in esperadas]\n    if _iguais(ob, es):\n        return\n    if not ordem and _iguais(sorted(ob, key=repr), sorted(es, key=repr)):\n        return\n    esp_txt, rec_txt = _tabela_txt(es), _tabela_txt(ob)\n    if len(ob) != len(es):\n        raise FalhaTeste(f\"{desc} deveria ter {len(es)} linha(s), mas teve {len(ob)}.\", esp_txt, rec_txt)\n    if ordem and sorted(ob, key=repr) == sorted(es, key=repr):\n        raise FalhaTeste(f\"{desc} tem as linhas certas, mas na ordem errada. Confira o ORDER BY.\", esp_txt, rec_txt)\n    for i, (a, b) in enumerate(zip(ob, es)):\n        if not _iguais(a, b):\n            if len(a) != len(b):\n                raise FalhaTeste(f\"{desc}: cada linha deveria ter {len(b)} coluna(s), mas tem {len(a)}. \"\n                                 \"Confira as colunas do SELECT.\", esp_txt, rec_txt)\n            raise FalhaTeste(f\"{desc}: a linha {i + 1} deveria ser {_r(b)}, mas foi {_r(a)}.\", esp_txt, rec_txt)\n    raise FalhaTeste(f\"{desc} est\u00e1 diferente do esperado.\", esp_txt, rec_txt)\n\n\ndef colunas_iguais(res, esperadas):\n    cols = [c.lower() for c in (res.colunas if isinstance(res, ResultadoSQL) else res)]\n    esp = [c.lower() for c in esperadas]\n    if cols != esp:\n        raise FalhaTeste(f\"As colunas do resultado deveriam ser {esperadas}, mas foram {res.colunas if isinstance(res, ResultadoSQL) else res}. \"\n                         \"Confira o SELECT e os apelidos (AS).\")\n\n\ndef _sql_sem_textos(sql):\n    sql = re.sub(r\"--[^\\n]*\", \" \", sql)\n    sql = re.sub(r\"/\\*.*?\\*/\", \" \", sql, flags=re.S)\n    sql = re.sub(r\"'(?:[^']|'')*'\", \"''\", sql)\n    return re.sub(r\"\\s+\", \" \", sql).upper()\n\n\ndef sql_usa(trecho, msg=None):\n    \"\"\"Confere que o SQL do aluno usa uma palavra-chave (fora de textos e coment\u00e1rios): sql_usa(\"ORDER BY\").\"\"\"\n    alvo = re.sub(r\"\\s+\", \" \", trecho.strip()).upper()\n    if not re.search(r\"(?<![A-Z_])\" + re.escape(alvo) + r\"(?![A-Z_])\", _sql_sem_textos(_CTX.codigo)):\n        raise FalhaTeste(msg or f\"Este exerc\u00edcio pede que voc\u00ea use {trecho} no SQL.\")\n\n\ndef sql_nao_usa(trecho, msg=None):\n    alvo = re.sub(r\"\\s+\", \" \", trecho.strip()).upper()\n    if re.search(r\"(?<![A-Z_])\" + re.escape(alvo) + r\"(?![A-Z_])\", _sql_sem_textos(_CTX.codigo)):\n        raise FalhaTeste(msg or f\"Neste exerc\u00edcio, n\u00e3o use {trecho}.\")\n\n\n# ----------------------------------------------------------------------------\n# Ajudantes para testar APIs feitas com o miniweb (trilha de Back-end)\n# ----------------------------------------------------------------------------\ndef pegar_app(r, nome=\"app\"):\n    \"\"\"Pega o App do miniweb criado pelo aluno (app = App()).\"\"\"\n    if nome not in r.ns:\n        raise FalhaTeste(f\"N\u00e3o encontrei a vari\u00e1vel `{nome}`. Crie o aplicativo com: {nome} = App()\")\n    app = r.ns[nome]\n    if not (hasattr(app, \"processar\") and hasattr(app, \"rotas\")):\n        raise FalhaTeste(f\"`{nome}` deveria ser um App do miniweb ({nome} = App()), mas \u00e9 {type(app).__name__}.\")\n    return app\n\n\ndef requisitar(app, metodo, url, json=None, cabecalhos=None):\n    \"\"\"Faz uma requisi\u00e7\u00e3o de teste ao App do aluno. Erros dentro da rota viram falhas amig\u00e1veis.\"\"\"\n    metodo = str(metodo).upper()\n    desc = f\"{metodo} {url}\"\n    resp, _ = _chamar(app.processar, (metodo, url), {\"json\": json, \"cabecalhos\": cabecalhos},\n                      desc=f\"a rota {desc}\")\n    if not (hasattr(resp, \"status\") and hasattr(resp, \"texto\")):\n        raise FalhaTeste(f\"{desc} deveria devolver uma resposta HTTP, mas veio {_r(resp)}.\")\n    return resp\n\n\ndef _frase_status(codigo):\n    from http import HTTPStatus\n    try:\n        return f\"{codigo} {HTTPStatus(codigo).phrase}\"\n    except ValueError:\n        return str(codigo)\n\n\ndef status_igual(resp, esperado, desc=\"A resposta\"):\n    \"\"\"Confere o status HTTP e mostra o corpo da resposta quando falha.\"\"\"\n    if resp.status != esperado:\n        corpo = resp.texto if len(resp.texto) <= 300 else resp.texto[:297] + \"...\"\n        raise FalhaTeste(f\"{desc} deveria ter status {_frase_status(esperado)}, mas teve {_frase_status(resp.status)}.\"\n                         + (f\"\\nCorpo da resposta: {corpo}\" if corpo else \"\"),\n                         str(esperado), str(resp.status))\n\n\ndef json_da_resposta(resp, desc=\"A resposta\"):\n    \"\"\"O corpo JSON da resposta (falha com mensagem clara se n\u00e3o for JSON).\"\"\"\n    try:\n        return resp.json()\n    except ValueError:\n        raise FalhaTeste(f\"{desc} deveria ter um corpo JSON, mas veio: {_r(resp.texto)}. \"\n                         \"Devolva um dict ou uma lista na rota.\") from None\n\n\n# ----------------------------------------------------------------------------\n# Testes escritos pelo aluno (trilha de Boas Pr\u00e1ticas)\n# ----------------------------------------------------------------------------\ndef testes_do_aluno(r):\n    \"\"\"Fun\u00e7\u00f5es test_* que o aluno escreveu (na ordem do c\u00f3digo).\"\"\"\n    return [(n, f) for n, f in r.ns.items()\n            if n.startswith(\"test\") and callable(f) and not isinstance(f, type)\n            and getattr(getattr(f, \"__code__\", None), \"co_filename\", \"\") == ARQUIVO]\n\n\ndef classes_de_teste(r):\n    return [c for c in r.ns.values()\n            if isinstance(c, type) and issubclass(c, unittest.TestCase) and c is not unittest.TestCase]\n\n\ndef rodar_testes_do_aluno(r, trocar=None):\n    \"\"\"Roda os testes do aluno (fun\u00e7\u00f5es test_* e classes unittest.TestCase).\n    trocar={\"nome\": funcao} substitui algo no c\u00f3digo do aluno antes de rodar.\n    Devolve uma lista de (nome_do_teste, passou, mensagem).\"\"\"\n    ns = r.ns\n    guardados = {}\n    for k, v in (trocar or {}).items():\n        guardados[k] = ns.get(k, _AUSENTE)\n        ns[k] = v\n    resultados = []\n    try:\n        for nome, f in testes_do_aluno(r):\n            try:\n                _chamar(f, (), {}, desc=f\"{nome}()\")\n                resultados.append((nome, True, \"\"))\n            except FalhaTeste as e:\n                resultados.append((nome, False, e.msg))\n        classes = classes_de_teste(r)\n        if classes:\n            carregador = unittest.TestLoader()\n            suite = unittest.TestSuite([carregador.loadTestsFromTestCase(c) for c in classes])\n            fluxo = io.StringIO()\n            velhos = (sys.stdout, sys.stderr)\n            sys.stdout = sys.stderr = io.StringIO()\n            try:\n                res = unittest.TextTestRunner(stream=fluxo, verbosity=0).run(suite)\n            finally:\n                sys.stdout, sys.stderr = velhos\n            ruins = {}\n            for caso, tb in res.failures + res.errors:\n                chave = f\"{type(caso).__name__}.{getattr(caso, '_testMethodName', caso.id().split('.')[-1])}\"\n                ruins[chave] = tb.strip().splitlines()[-1] if tb.strip() else \"falhou\"\n            for c in classes:\n                for nome in carregador.getTestCaseNames(c):\n                    chave = f\"{c.__name__}.{nome}\"\n                    resultados.append((chave, chave not in ruins, ruins.get(chave, \"\")))\n    finally:\n        for k, v in guardados.items():\n            if v is _AUSENTE:\n                ns.pop(k, None)\n            else:\n                ns[k] = v\n    return resultados\n\n\nclass _Ausente:\n    pass\n\n\n_AUSENTE = _Ausente()\n\n\ndef avaliar_testes(r, nome, correta, mutantes, minimo=1):\n    \"\"\"Confere os testes do aluno: passam com a vers\u00e3o correta de `nome` e pegam cada vers\u00e3o com bug.\n    mutantes = [(\"descri\u00e7\u00e3o do bug\", funcao_com_bug), ...]\"\"\"\n    total = len(testes_do_aluno(r)) + sum(len(unittest.TestLoader().getTestCaseNames(c)) for c in classes_de_teste(r))\n    if total < minimo:\n        raise FalhaTeste(f\"Escreva pelo menos {minimo} teste(s): fun\u00e7\u00f5es com nome come\u00e7ando por test_ \"\n                         \"(ou m\u00e9todos test_ numa classe unittest.TestCase).\")\n    res = rodar_testes_do_aluno(r, {nome: correta})\n    for teste, ok, msg in res:\n        if not ok:\n            raise FalhaTeste(f\"Com a vers\u00e3o CORRETA de {nome}, o teste {teste} falhou \u2014 ent\u00e3o ele est\u00e1 esperando \"\n                             f\"a coisa errada:\\n{msg}\")\n    for descricao, mutante in mutantes:\n        res = rodar_testes_do_aluno(r, {nome: mutante})\n        if all(ok for _, ok, _ in res):\n            raise FalhaTeste(f\"Seus testes n\u00e3o perceberam este bug: {descricao}. \"\n                             \"Escreva um teste que falhe quando isso acontece.\")\n\n\n# ----------------------------------------------------------------------------\n# Logging e an\u00e1lise de c\u00f3digo limpo\n# ----------------------------------------------------------------------------\nclass _CapturaLogs(logging.Handler):\n    def __init__(self):\n        super().__init__(logging.DEBUG)\n        self.registros = []\n\n    def emit(self, registro):\n        try:\n            self.registros.append((registro.levelname, registro.getMessage(), registro.name))\n        except Exception:  # noqa: BLE001\n            self.registros.append((registro.levelname, str(registro.msg), registro.name))\n\n\ndef com_logs(f, *args, **kwargs):\n    \"\"\"Chama f(*args) capturando o que ela registrou com logging. Devolve (valor, [(nivel, mensagem, logger)]).\"\"\"\n    captura = _CapturaLogs()\n    raiz = logging.getLogger()\n    nivel_antes = raiz.level\n    raiz.addHandler(captura)\n    raiz.setLevel(logging.DEBUG)\n    try:\n        valor = chamar(f, *args, **kwargs)\n    finally:\n        raiz.removeHandler(captura)\n        raiz.setLevel(nivel_antes)\n    return valor, captura.registros\n\n\ndef _reiniciar_logging():\n    raiz = logging.getLogger()\n    for h in raiz.handlers[:]:\n        raiz.removeHandler(h)\n    raiz.setLevel(logging.WARNING)\n    for nome in list(logging.Logger.manager.loggerDict):\n        lg = logging.getLogger(nome)\n        if not nome.startswith((\"asyncio\", \"concurrent\")):\n            for h in lg.handlers[:]:\n                lg.removeHandler(h)\n            lg.setLevel(logging.NOTSET)\n            lg.propagate = True\n\n\ndef arvore():\n    \"\"\"A \u00e1rvore sint\u00e1tica (ast) do c\u00f3digo do aluno.\"\"\"\n    return _CTX.arvore\n\n\ndef funcoes_definidas():\n    \"\"\"Nomes das fun\u00e7\u00f5es definidas no c\u00f3digo (inclusive m\u00e9todos), na ordem.\"\"\"\n    return [n.name for n in ast.walk(_CTX.arvore) if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))]\n\n\ndef linhas_da_funcao(nome):\n    fn = funcao_definida(nome)\n    if fn is None:\n        raise FalhaTeste(f\"N\u00e3o encontrei a fun\u00e7\u00e3o `{nome}`.\")\n    corpo = fn.body\n    if corpo and isinstance(corpo[0], ast.Expr) and isinstance(getattr(corpo[0], \"value\", None), ast.Constant) \\\n            and isinstance(corpo[0].value.value, str):\n        corpo = corpo[1:] or corpo\n    return corpo[-1].end_lineno - corpo[0].lineno + 1\n\n\ndef tem_docstring(nome):\n    fn = funcao_definida(nome)\n    return fn is not None and ast.get_docstring(fn) is not None\n\n\ndef tem_dicas_de_tipo(nome):\n    fn = funcao_definida(nome)\n    if fn is None:\n        return False\n    args = [a for a in fn.args.args + fn.args.kwonlyargs if a.arg not in (\"self\", \"cls\")]\n    return fn.returns is not None and all(a.annotation is not None for a in args)\n\n\ndef numeros_magicos(permitidos=(0, 1, -1, 2, 100)):\n    \"\"\"N\u00fameros escritos direto dentro de fun\u00e7\u00f5es (fora de constantes MAI\u00daSCULAS do m\u00f3dulo).\"\"\"\n    achados = []\n    for fn in ast.walk(_CTX.arvore):\n        if isinstance(fn, (ast.FunctionDef, ast.AsyncFunctionDef)):\n            for n in ast.walk(fn):\n                if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)) and not isinstance(n.value, bool):\n                    if n.value not in permitidos:\n                        achados.append(n.value)\n    return achados\n\n\ndef constantes_do_modulo():\n    \"\"\"Nomes em MAI\u00daSCULAS atribu\u00eddos no n\u00edvel do m\u00f3dulo.\"\"\"\n    nomes = []\n    for n in _CTX.arvore.body:\n        alvos = n.targets if isinstance(n, ast.Assign) else [n.target] if isinstance(n, ast.AnnAssign) else []\n        for a in alvos:\n            if isinstance(a, ast.Name) and a.id.isupper():\n                nomes.append(a.id)\n    return nomes\n\n\ndef nomes_atribuidos():\n    \"\"\"Todos os nomes de vari\u00e1veis que recebem valor (=, for, par\u00e2metros).\"\"\"\n    nomes = set()\n    for n in ast.walk(_CTX.arvore):\n        if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Store):\n            nomes.add(n.id)\n        elif isinstance(n, ast.arg):\n            nomes.add(n.arg)\n    return nomes\n\n\n_AJUDANTES = {\n    \"rodar\": rodar, \"falhar\": falhar, \"verificar\": verificar, \"saida_igual\": saida_igual,\n    \"saida_contem\": saida_contem, \"ultima_linha\": ultima_linha, \"pegar_var\": pegar_var,\n    \"pegar_func\": pegar_func, \"pegar_classe\": pegar_classe, \"atributo\": atributo,\n    \"chamar\": chamar, \"chamar_com_saida\": chamar_com_saida, \"igual\": igual,\n    \"conta_no\": conta_no, \"usa\": usa, \"nao_usa\": nao_usa, \"conta_chamadas\": conta_chamadas,\n    \"usa_chamada\": usa_chamada, \"nao_usa_chamada\": nao_usa_chamada, \"usa_operador\": usa_operador,\n    \"usa_fstring\": usa_fstring, \"funcao_definida\": funcao_definida, \"e_recursiva\": e_recursiva,\n    \"texto_do_codigo\": texto_do_codigo, \"criar_arquivo\": criar_arquivo, \"ler_arquivo\": ler_arquivo,\n    \"apagar_arquivo\": apagar_arquivo, \"FalhaTeste\": FalhaTeste, \"Resultado\": Resultado,\n    \"random\": random, \"math\": math, \"ast\": ast,\n    # SQL\n    \"rodar_sql\": rodar_sql, \"consulta\": consulta, \"conectar_banco\": conectar_banco, \"tabela\": tabela,\n    \"colunas_da_tabela\": colunas_da_tabela, \"linhas_iguais\": linhas_iguais, \"colunas_iguais\": colunas_iguais,\n    \"sql_usa\": sql_usa, \"sql_nao_usa\": sql_nao_usa, \"ResultadoSQL\": ResultadoSQL, \"sqlite3\": sqlite3,\n    # APIs (miniweb)\n    \"pegar_app\": pegar_app, \"requisitar\": requisitar, \"status_igual\": status_igual,\n    \"json_da_resposta\": json_da_resposta,\n    # testes do aluno, logging, c\u00f3digo limpo\n    \"testes_do_aluno\": testes_do_aluno, \"classes_de_teste\": classes_de_teste,\n    \"rodar_testes_do_aluno\": rodar_testes_do_aluno, \"avaliar_testes\": avaliar_testes,\n    \"com_logs\": com_logs, \"logging\": logging, \"unittest\": unittest,\n    \"arvore\": arvore, \"funcoes_definidas\": funcoes_definidas, \"linhas_da_funcao\": linhas_da_funcao,\n    \"tem_docstring\": tem_docstring, \"tem_dicas_de_tipo\": tem_dicas_de_tipo, \"numeros_magicos\": numeros_magicos,\n    \"constantes_do_modulo\": constantes_do_modulo, \"nomes_atribuidos\": nomes_atribuidos,\n    \"json\": json, \"re\": re,\n}\n\n\ndef _rodar_testes(codigo, testes, arquivos=None, tempo=TEMPO_TESTES, banco=None, banco_arquivo=None, linguagem=\"python\",\n                  leniente=None):\n    res = {\"ok\": False, \"testes\": [], \"sintaxe\": None}\n    _Leniencia.ativa = isinstance(leniente, dict)\n    _Leniencia.caixa = bool(_Leniencia.ativa and leniente.get(\"caixa\"))\n    _Leniencia.espacos = bool(_Leniencia.ativa and leniente.get(\"espacos\"))\n    _Leniencia.execucoes = 0\n    _registrar_fonte(codigo)\n    if linguagem == \"sql\":\n        arvore = None\n    else:\n        try:\n            arvore = ast.parse(codigo, ARQUIVO)\n        except SyntaxError as e:\n            res[\"sintaxe\"] = _info_erro(e)\n            return res\n    _CTX.codigo = codigo\n    _CTX.arvore = arvore\n    _CTX.arquivos = arquivos\n    _CTX.banco = banco\n    _CTX.banco_arquivo = (banco_arquivo or \"jogo.db\") if (banco and linguagem != \"sql\") else None\n    _CTX.linguagem = linguagem\n    todos = True\n    esgotou = False\n    fim_do_prazo = time.perf_counter() + tempo\n    for nome, fonte in testes:\n        env = dict(_AJUDANTES)\n        item = {\"nome\": nome, \"ok\": True}\n        if esgotou:\n            item.update(ok=False, msg=\"N\u00e3o rodou: um teste anterior estourou o tempo.\")\n            todos = False\n            res[\"testes\"].append(item)\n            continue\n        _Leniencia.dicas = []\n        _Leniencia.estrutura = []\n        try:\n            _preparar_arquivos(arquivos)\n            _Relogio.limite = fim_do_prazo\n            sys.settrace(_rastro_global)\n            exec(compile(textwrap.dedent(fonte).strip(\"\\n\") + \"\\n\", \"<teste>\", \"exec\"), env)\n        except FalhaTeste as f:\n            item.update(ok=False, msg=f.msg, esperado=f.esperado, recebido=f.recebido)\n        except _SinalSaidaDemais:\n            item.update(ok=False, msg=\"Seu c\u00f3digo mostrou texto demais \u2014 parece um loop infinito.\")\n        except _SinalTempo as t:\n            item.update(ok=False, msg=f\"Seu c\u00f3digo demorou demais e foi interrompido na linha {t.linha}. \"\n                                      \"Parece um loop infinito.\")\n        except BaseException as e:  # noqa: BLE001\n            item.update(ok=False, msg=\"O teste n\u00e3o conseguiu conferir seu c\u00f3digo:\\n\" + _resumo_erro(e))\n        finally:\n            _desarmar_relogio()\n        if not item[\"ok\"] and (\"demorou demais\" in item.get(\"msg\", \"\")):\n            esgotou = time.perf_counter() > fim_do_prazo\n        if item[\"ok\"] and (_Leniencia.dicas or _Leniencia.estrutura):\n            item[\"dicas\"] = list(_Leniencia.dicas)\n            if _Leniencia.estrutura:\n                item[\"estrutura\"] = list(_Leniencia.estrutura)\n        res[\"testes\"].append(item)\n    for item in res[\"testes\"]:\n        estrutura = item.pop(\"estrutura\", None)\n        if estrutura:\n            # sem nenhum teste que rode o programa, as checagens de estrutura s\u00e3o tudo o que a aula confere\n            if not _Leniencia.execucoes:\n                item.update(ok=False, msg=estrutura[0])\n                item.pop(\"dicas\", None)\n            else:\n                item[\"dicas\"] = item.get(\"dicas\", []) + [f\"Sugest\u00e3o da aula: {m}\" for m in estrutura]\n        todos = todos and item[\"ok\"]\n    res[\"ok\"] = todos\n    _Leniencia.ativa = False\n    return res\n\n\n# ----------------------------------------------------------------------------\n# Jogo da cobrinha (projeto final): o estado vive aqui, no Python\n# ----------------------------------------------------------------------------\nclass _Jogo:\n    ns = None\n    estado = None\n\n\ndef _pos(p):\n    return [int(p[0]), int(p[1])]\n\n\ndef _estado_para_js(estado):\n    return {\n        \"cobra\": [_pos(p) for p in estado[\"cobra\"]],\n        \"comida\": _pos(estado[\"comida\"]) if estado.get(\"comida\") is not None else None,\n        \"pontos\": int(estado.get(\"pontos\", 0)),\n        \"vivo\": bool(estado.get(\"vivo\", True)),\n        \"direcao\": str(estado.get(\"direcao\", \"\")),\n    }\n\n\ndef _api_jogo_iniciar(payload):\n    p = json.loads(payload)\n    _armar_relogio(3.0)\n    try:\n        r = _executar(p[\"code\"], [], p.get(\"seed\"), eco=False)\n    finally:\n        _desarmar_relogio()\n    if r.fim == \"erro\":\n        return json.dumps({\"erro\": _info_erro(r.erro)})\n    if r.fim in (\"tempo\", \"limite\", \"entrada\"):\n        return json.dumps({\"erro\": {\"tipo\": \"Erro\", \"texto\": \"O c\u00f3digo do jogo n\u00e3o terminou de carregar \"\n                                    \"(loop infinito, texto demais ou input() fora das fun\u00e7\u00f5es).\",\n                                    \"dica\": \"Deixe s\u00f3 as fun\u00e7\u00f5es e o c\u00f3digo de teste fora delas.\", \"linha\": None}})\n    ns = r.ns\n    for nome in (\"passo\", \"nova_comida\"):\n        if not callable(ns.get(nome)):\n            return json.dumps({\"erro\": {\"tipo\": \"Faltando\", \"texto\": f\"N\u00e3o encontrei a fun\u00e7\u00e3o {nome}.\",\n                                        \"dica\": \"O jogo precisa das fun\u00e7\u00f5es passo e nova_comida.\", \"linha\": None}})\n    w, h = int(p.get(\"largura\", 16)), int(p.get(\"altura\", 12))\n    meio = h // 2\n    cobra = [(3, meio), (2, meio), (1, meio)]\n    try:\n        _armar_relogio(2.0)\n        comida, _ = _chamar(ns[\"nova_comida\"], (list(cobra), w, h), {})\n    except FalhaTeste as f:\n        return json.dumps({\"erro\": {\"tipo\": \"Erro\", \"texto\": f.msg, \"dica\": \"\", \"linha\": None}})\n    finally:\n        _desarmar_relogio()\n    _Jogo.ns = ns\n    _Jogo.estado = {\"cobra\": cobra, \"direcao\": \"direita\", \"comida\": comida, \"pontos\": 0,\n                    \"vivo\": True, \"largura\": w, \"altura\": h}\n    return json.dumps({\"estado\": _estado_para_js(_Jogo.estado)})\n\n\ndef _api_jogo_passo(payload):\n    p = json.loads(payload)\n    if _Jogo.ns is None:\n        return json.dumps({\"erro\": {\"tipo\": \"Erro\", \"texto\": \"Jogo n\u00e3o iniciado.\", \"dica\": \"\", \"linha\": None}})\n    try:\n        _armar_relogio(1.0)\n        try:\n            novo, _ = _chamar(_Jogo.ns[\"passo\"], (_Jogo.estado, p.get(\"pedida\") or _Jogo.estado[\"direcao\"]), {})\n        finally:\n            _desarmar_relogio()\n        if not isinstance(novo, dict):\n            raise FalhaTeste(f\"passo() deveria devolver o dicion\u00e1rio do estado, mas devolveu {_r(novo)}.\")\n        _Jogo.estado = novo\n        return json.dumps({\"estado\": _estado_para_js(novo)})\n    except FalhaTeste as f:\n        return json.dumps({\"erro\": {\"tipo\": \"Erro\", \"texto\": f.msg, \"dica\": \"\", \"linha\": None}})\n    except Exception as e:  # noqa: BLE001\n        return json.dumps({\"erro\": {\"tipo\": type(e).__name__, \"texto\": f\"O estado do jogo ficou inv\u00e1lido: {e}\",\n                                    \"dica\": \"Confira se passo() devolve o estado com cobra, comida, pontos e vivo.\",\n                                    \"linha\": None}})\n\n\n# ----------------------------------------------------------------------------\n# Pontos de entrada chamados pelo navegador (JSON entra, JSON sai)\n# ----------------------------------------------------------------------------\ndef _api_run(payload):\n    p = json.loads(payload)\n    _preparar_arquivos(p.get(\"files\"))\n    if p.get(\"banco\"):\n        _preparar_banco(p[\"banco\"], p.get(\"banco_arquivo\") or \"jogo.db\")\n    _armar_relogio(float(p.get(\"tempo\", TEMPO_EXECUTAR)))\n    try:\n        r = _executar(p[\"code\"], p.get(\"inputs\"), p.get(\"seed\"), eco=True)\n    finally:\n        _desarmar_relogio()\n    res = {\"saida\": r.saida, \"fim\": r.fim}\n    if r.fim == \"entrada\":\n        res[\"prompt\"] = r.prompt_pendente\n    elif r.fim == \"erro\":\n        res[\"erro\"] = _info_erro(r.erro)\n    elif r.fim == \"tempo\":\n        res[\"linha\"] = r.linha_tempo\n    return json.dumps(res)\n\n\ndef _api_test(payload):\n    p = json.loads(payload)\n    testes = [(t[0], t[1]) for t in p[\"tests\"]]\n    return json.dumps(_rodar_testes(p[\"code\"], testes, p.get(\"files\"), banco=p.get(\"banco\"),\n                                    banco_arquivo=p.get(\"banco_arquivo\"), linguagem=p.get(\"linguagem\") or \"python\",\n                                    leniente=p.get(\"leniente\")),\n                      default=str)\n\n\ndef _api_sql(payload):\n    \"\"\"Bot\u00e3o Executar das aulas de SQL: roda os comandos e devolve tabelas.\"\"\"\n    p = json.loads(payload)\n    try:\n        con, blocos = _executar_sql(p[\"code\"], p.get(\"banco\"))\n        con.close()\n    except ErroSQL as e:\n        return json.dumps({\"erro\": _info_erro_sql(e), \"indice\": e.indice}, default=str)\n    except sqlite3.Error as e:\n        return json.dumps({\"erro\": {\"tipo\": type(e).__name__, \"texto\": f\"Erro ao preparar o banco: {e}\", \"dica\": \"\", \"linha\": None}})\n    return json.dumps({\"blocos\": blocos}, default=str)\n\n\ndef _api_info():\n    return json.dumps({\"python\": sys.version.split()[0]})\n";
let pyodide = null;

// A biblioteca padrão do Python vem como JSON (base64): o site de Artifacts não serve .zip.
// O Pyodide pede o .zip com fetch(); respondemos esse pedido com os bytes decodificados.
const STDLIB_ZIP = new URL("./py/python_stdlib.zip", import.meta.url).href;
const STDLIB_JSON = new URL("./py/python_stdlib.json", import.meta.url).href;
const fetchOriginal = self.fetch.bind(self);
let stdlibBytes = null;
function base64ParaBytes(b64) {
  if (typeof Uint8Array.fromBase64 === "function") return Uint8Array.fromBase64(b64);
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
self.fetch = async (entrada, opcoes) => {
  const url = typeof entrada === "string" ? entrada : entrada instanceof URL ? entrada.href : entrada && entrada.url;
  if (url === STDLIB_ZIP) {
    if (!stdlibBytes) {
      const r = await fetchOriginal(STDLIB_JSON);
      if (!r.ok) throw new Error("não consegui baixar a biblioteca padrão do Python (" + r.status + ")");
      stdlibBytes = base64ParaBytes((await r.json()).b64);
    }
    return new Response(stdlibBytes, { status: 200, headers: { "Content-Type": "application/octet-stream" } });
  }
  return fetchOriginal(entrada, opcoes);
};

const ready = (async () => {
  pyodide = await loadPyodide({
    indexURL: new URL("./py/", import.meta.url).href,
    stdLibURL: STDLIB_ZIP,
    stdout: () => {},
    stderr: () => {},
  });
  pyodide.runPython(HARNESS);
  const info = JSON.parse(pyodide.globals.get("_api_info")());
  info.pyodide = pyodide.version;
  postMessage({ type: "ready", info });
})().catch((err) => {
  postMessage({ type: "fatal", error: String((err && (err.stack || err.message)) || err) });
  throw err;
});

// Resultados de SQL: o JSON.parse transformaria o REAL 9.0 em 9. Para a tabela mostrar o número como o
// SQLite e o Python mostram, cada decimal vira {"$decimal": "9.0"} (fora de textos; inteiros ficam iguais).
function marcarDecimais(json) {
  let out = "";
  let i = 0;
  const n = json.length;
  while (i < n) {
    const c = json[i];
    if (c === '"') {
      let j = i + 1;
      while (j < n && json[j] !== '"') j += json[j] === "\\" ? 2 : 1;
      out += json.slice(i, j + 1);
      i = j + 1;
    } else if (json.startsWith("-Infinity", i)) { out += '{"$decimal":"-inf"}'; i += 9; }
    else if (json.startsWith("Infinity", i)) { out += '{"$decimal":"inf"}'; i += 8; }
    else if (json.startsWith("NaN", i)) { out += '{"$decimal":"nan"}'; i += 3; }
    else if (c === "-" || (c >= "0" && c <= "9")) {
      let j = i + 1;
      while (j < n && "0123456789.eE+-".includes(json[j])) j++;
      const num = json.slice(i, j);
      out += /[.eE]/.test(num) ? `{"$decimal":"${num}"}` : num;
      i = j;
    } else { out += c; i++; }
  }
  return out;
}

self.onmessage = async (ev) => {
  const { id, cmd, payload } = ev.data || {};
  try {
    await ready;
    const fn = pyodide.globals.get("_api_" + cmd);
    if (!fn) throw new Error("comando desconhecido: " + cmd);
    const out = fn(JSON.stringify(payload || {}));
    if (fn.destroy) fn.destroy();
    postMessage({ id, ok: true, result: JSON.parse(cmd === "sql" ? marcarDecimais(out) : out) });
  } catch (err) {
    postMessage({ id, ok: false, error: String((err && err.message) || err) });
  }
};
